"""Tests for agentcontext.commits: the trailer extraction, the scopes of the heuristics, the
heuristics against every field of a commit, the ids of the matched heuristics, the attribution
details and the shard reader. Every row of heuristics/ai_commit_patterns.csv has a commit of its
own in TestEveryRuleHasACase, checked against the rows that it matches, so that a regression of
a pattern is caught without a clone. Reading the commit history of a clone is tested where the
cloning step does it, in tests.test_steps_repository_cloning.

The names and addresses of people in the cases are fictional, in a form that keeps what a row
reads, and the repository and the commit beside a case identify it. A pattern that names an address
of a person keeps that address here, because the case tests it.

Requirements: Python 3.14, git on PATH (stdlib only)
Run with:  python3 -m unittest tests.test_commits -v
"""

import csv
import json
import os
import re
import shutil
import string
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

from agentcontext import REPO_ROOT
from agentcontext import commits as _mod
from agentcontext import heuristics as _heuristics
from agentcontext.commits import AI_COMMIT_PATTERNS, _extract_trailers, detect_ai_tools_in_fields
from agentcontext.git import history as _meta
from tests import _ambient_env

# Each heuristic's pattern by its id, which is what `matched_rules_in_fields` returns.
PATTERN_OF = {row["id"]: row["pattern"] for row in AI_COMMIT_PATTERNS}

_saved_credentials = {}

def setUpModule():
    # An ambient GITHUB_TOKEN changes the clone URL that these tests redirect, and the suite
    # would then pass or fail depending on the machine rather than on the code.
    # tests/_ambient_env.py lists the variables and the reasons.
    _ambient_env.take(_saved_credentials)


def tearDownModule():
    _ambient_env.restore(_saved_credentials)


class TestExtractTrailers(unittest.TestCase):

    def test_empty_body_returns_empty(self):
        self.assertEqual(_extract_trailers(""), "")

    def test_single_trailer_returned(self):
        body = "Fix the bug\n\nCo-authored-by: Claude <noreply@anthropic.com>"
        result = _extract_trailers(body)
        self.assertIn("Co-authored-by: Claude", result)

    def test_multiple_trailers_returned(self):
        body = "Fix\n\nCo-authored-by: Claude <noreply@anthropic.com>\nSigned-off-by: Alice <a@b.com>"
        result = _extract_trailers(body)
        self.assertIn("Co-authored-by", result)
        self.assertIn("Signed-off-by", result)

    def test_non_trailer_line_is_not_included(self):
        body = "Fix the bug\nThis is prose\nCo-authored-by: Claude <noreply@anthropic.com>"
        result = _extract_trailers(body)
        # Only the line with the form of a trailer is kept, and the prose around it is not.
        self.assertIn("Co-authored-by", result)
        self.assertNotIn("This is prose", result)

    def test_text_after_a_trailer_is_not_included(self):
        body = "Co-authored-by: Claude <noreply@anthropic.com>\n\nThis is not a trailer"
        result = _extract_trailers(body)
        # The trailer is kept, and the line below it does not have the form of a trailer.
        self.assertIn("Co-authored-by: Claude", result)
        self.assertNotIn("This is not a trailer", result)

    def test_trailer_followed_by_squashed_message_is_extracted(self):
        # A squash merge concatenates the messages of the commits that it replaces, and the
        # trailer is then often not the last line of the body.
        body = ("Add OSC8 hyperlink support\n\n"
                "Co-Authored-By: Claude <noreply@anthropic.com>\n\n"
                "* chore(settings.json): add DISABLE_AUTOUPDATER")
        result = _extract_trailers(body)
        self.assertIn("Co-Authored-By: Claude", result)
        self.assertNotIn("chore(settings.json)", result)

    def test_two_trailer_blocks_separated_by_a_blank_line(self):
        # Both co-authors count. Taking only the final block would drop the first.
        body = ("Co-Authored-By: Claude <noreply@anthropic.com>\n\n"
                "Co-Authored-By: Autopilot <autopilot@openagents.com>")
        result = _extract_trailers(body)
        self.assertIn("Claude", result)
        self.assertIn("Autopilot", result)

    def test_trailer_followed_by_cherry_pick_line_is_extracted(self):
        body = ("Fix a thing\n\n"
                "Co-authored-by: gemini-code-assist[bot] <1+gemini-code-assist[bot]@users.noreply.github.com>\n"
                "Co-authored-by: Jane Doe <person154@example.com>\n"
                "(cherry picked from commit a63e67823def9f91256f1619b57a8c570a72b351)")
        result = _extract_trailers(body)
        self.assertIn("gemini-code-assist", result)
        self.assertNotIn("cherry picked", result)

    def test_a_trailer_without_a_space_after_the_colon_is_extracted(self):
        """git interpret-trailers reads this line as a trailer. The extraction therefore requires
        no space after the colon, and the commit is not classified as a person's."""
        body = "Fix\n\nCo-authored-by:Claude <noreply@anthropic.com>"
        self.assertEqual(_extract_trailers(body), "Co-authored-by:Claude <noreply@anthropic.com>")
        self.assertEqual(detect_ai_tools_in_fields("Dev", "d@example.com", "Dev",
                                                   "d@example.com", "Fix", body), ["Claude"])

    def test_a_token_with_no_value_or_a_sentence_before_the_colon_is_not_a_trailer(self):
        # The form still excludes both once the space is optional.
        body = "Co-authored-by:\nI used co-authored-by:claude once\nSee the notes :here"
        self.assertEqual(_extract_trailers(body), "")

    def test_line_with_space_in_token_is_excluded(self):
        # "Link to Devin run:" has a space in the token and is no valid trailer
        body = "Fix\n\nLink to Devin run: https://app.devin.ai/sessions/abc\nCo-authored-by: Devin <d@devin.ai>"
        result = _extract_trailers(body)
        self.assertNotIn("Link to Devin run", result)

    def test_prose_body_with_no_trailers_returns_empty(self):
        body = "This commit fixes the login bug.\n\nUsers were being logged out unexpectedly."
        result = _extract_trailers(body)
        self.assertEqual(result, "")

    def test_coauthored_in_prose_is_not_extracted_as_trailer(self):
        # "co-authored-by" inside a prose sentence is not a trailer line
        body = "I used co-authored-by convention informally here.\nMore prose."
        result = _extract_trailers(body)
        self.assertEqual(result, "")


class TestTheHeuristicsSayWhichScopeEachPatternIsMatchedIn(unittest.TestCase):
    """The scope is a column of the heuristics, not computed from the pattern text by testing
    whether the string begins with a trailer token. Computed that way, a new attribution line
    with a pattern that does not start with its own token would be put in the full-body scope
    without any message."""

    def _scope(self, pattern: str) -> str:
        for row in AI_COMMIT_PATTERNS:
            if row["pattern"] == pattern:
                return row["scope"]
        self.fail(f"{pattern} is not in the heuristics")

    def test_co_authored_by_is_a_trailer(self):
        self.assertEqual(self._scope(CLAUDE_CO_AUTHORED), "trailer")

    def test_generated_by_is_a_trailer(self):
        self.assertEqual(self._scope(CLAUDE_GENERATED), "trailer")

    def test_made_with_is_a_trailer(self):
        self.assertEqual(self._scope(r"made-with:\s*cursor"), "trailer")

    def test_a_merge_message_is_full_body(self):
        self.assertEqual(self._scope(_pattern_of("copilot-full-body-01")), "full_body")

    def test_prose_is_full_body(self):
        self.assertEqual(self._scope(
            _pattern_of("claude-full-body-01")),
            "full_body")

    def test_an_identity_rule_is_the_author_scope(self):
        self.assertEqual(self._scope(r"noreply@anthropic\.com"), "author")


class TestDetectAiToolsInFields(unittest.TestCase):
    """
    Tests the detection function directly, without any git or file system
    operation: the tool that a commit is attributed to, and the commits that must be
    attributed to none. TestEveryRuleHasACase tests which heuristic matched, with one
    commit per heuristic.
    """

    def _detect(self, subject="", body="", author_name="", author_email="",
                committer_name="", committer_email="", check_author=True):
        return detect_ai_tools_in_fields(
            author_name, author_email, committer_name, committer_email,
            subject, body, check_author=check_author,
        )

    # -- no signals ----------------------------------------------------------

    def test_empty_commit_returns_empty(self):
        self.assertEqual(self._detect(), [])

    def test_plain_commit_message_returns_empty(self):
        self.assertEqual(self._detect(subject="fix: resolve login bug"), [])

    def test_ai_generated_in_subject_does_not_match(self):
        # A prose description must not trigger detection
        self.assertEqual(
            self._detect(subject="Add AI-generated tests"),
            [],
        )

    def test_ai_generated_in_body_does_not_match(self):
        self.assertEqual(
            self._detect(subject="[devkit] replace with ai-generated dialog"),
            [],
        )

    # -- Claude --------------------------------------------------------------

    def test_co_authored_by_claude_detects_claude(self):
        body = "Fix bug\n\nCo-authored-by: Claude <noreply@anthropic.com>"
        self.assertIn("Claude", self._detect(body=body))

    def test_co_authored_by_claude_model_name_detects_claude(self):
        # Claude Code's format includes the model name.
        body = "Fix\n\nCo-Authored-By: Claude Sonnet 4.6 <noreply@anthropic.com>"
        self.assertIn("Claude", self._detect(body=body))

    def test_co_authored_by_claude_case_insensitive(self):
        body = "Fix\n\nCO-AUTHORED-BY: CLAUDE <noreply@anthropic.com>"
        self.assertIn("Claude", self._detect(body=body))

    def test_generated_by_claude_detects_claude(self):
        body = "Fix\n\nGenerated-by: claude"
        self.assertIn("Claude", self._detect(body=body))

    def test_this_commit_generated_by_claude_detects_claude(self):
        self.assertIn("Claude", self._detect(
            subject="This commit was generated by claude"
        ))

    def test_this_pr_created_by_claude_detects_claude(self):
        self.assertIn("Claude", self._detect(
            subject="This PR was created by Claude"
        ))

    def test_anthropic_email_in_author_detects_claude(self):
        self.assertIn("Claude", self._detect(author_email="noreply@anthropic.com"))

    def test_an_address_naming_claude_at_anthropic_detects_claude(self):
        for email in ("claude@anthropic.com", "claude-opus-4.5@anthropic.com",
                      "claude4.5o@anthropic.com"):
            with self.subTest(email=email):
                self.assertEqual(self._detect(author_name="Dev", author_email=email),
                                 ["Claude"])

    def test_a_person_s_own_anthropic_address_names_no_tool(self):
        """People commit under their own anthropic.com addresses, among them in
        electron/electron and google/gvisor, and the heuristic therefore does not match the
        whole domain."""
        for email in ("person171@anthropic.com", "first198.last@anthropic.com", "person126@anthropic.com"):
            with self.subTest(email=email):
                self.assertEqual(self._detect(author_name="A Person", author_email=email), [])
                self.assertEqual(self._detect(committer_name="A Person",
                                              committer_email=email), [])
        self.assertEqual(self._detect(
            author_name="A Person", author_email="person@anthropic.com",
            body="Fix\n\nCo-authored-by: Claude <noreply@anthropic.com>"), ["Claude"])

    def test_assisted_by_trailer_detects_each_tool(self):
        # A third trailer token beside co-authored-by and generated-by, which the Linux
        # kernel adopted in Documentation/process/coding-assistants.rst. Gemini alone names
        # no product, and the Gemini case names the CLI (see
        # test_a_gemini_credit_naming_no_product_is_not_gemini).
        for tool, name in (("Claude", "claude"), ("Copilot", "copilot"),
                           ("Cursor", "cursor"), ("Codex", "codex"),
                           ("Gemini", "gemini-cli")):
            with self.subTest(tool):
                body = "Fix the bug\n\nAssisted-by: %s-opus-4-6" % name
                self.assertIn(tool, self._detect(body=body))

    def test_assisted_by_is_trailer_scoped_not_prose(self):
        # The same restriction as for the other trailer tokens: a sentence that mentions
        # the convention is not an attribution.
        body = "We discussed whether assisted-by claude should be required here."
        self.assertEqual(self._detect(body=body), [])

    def test_assisted_by_with_vendor_prefix_detects_the_tool(self):
        # The co-authored-by patterns allow "github copilot" and "openai codex", and the
        # assisted-by patterns allow them too.
        self.assertIn("Copilot", self._detect(body="x\n\nAssisted-by: GitHub Copilot"))
        self.assertIn("Codex", self._detect(body="x\n\nAssisted-by: OpenAI Codex"))

    def test_gemini_code_assist_spaced_name_detects_gemini(self):
        # The display name uses spaces, and gemini-code-assist[bot] uses hyphens.
        self.assertIn("Gemini", self._detect(author_name="Gemini Code Assist"))

    def test_gemini_coder_prose_does_not_detect_gemini(self):
        # The spaced pattern is the full "Gemini Code Assist" phrase, and a name that
        # merely starts "Gemini Code..." does not match.
        self.assertEqual(self._detect(author_name="Gemini Coder Fanclub"), [])

    def test_openai_codex_spaced_name_detects_codex(self):
        # The display name uses a space, not a hyphen.
        self.assertIn("Codex", self._detect(author_name="OpenAI Codex"))

    def test_openai_email_domain_detects_codex(self):
        self.assertIn("Codex", self._detect(author_email="codex@openai.com"))

    def test_chatgpt_codex_connector_detects_codex(self):
        self.assertIn("Codex", self._detect(
            author_name="chatgpt-codex-connector[bot]",
            author_email="12345+bot@users.noreply.github.com"))

    def test_unrelated_openai_email_does_not_detect_codex(self):
        # The email heuristic requires "codex" before the domain, and ordinary OpenAI staff
        # addresses do not match.
        self.assertEqual(self._detect(author_email="person157@openai.com"), [])

    def test_the_advanced_security_account_alone_is_not_copilot(self):
        # GitHub Advanced Security commits under this account for more than Autofix, a
        # dependency graph submission among them. An Autofix suggestion credits Copilot in
        # its co-author line, which the trailer heuristics match.
        self.assertNotIn("Copilot", self._detect(
            author_name="github-advanced-security[bot]",
            author_email="62310815+github-advanced-security[bot]@users.noreply.github.com"))
        self.assertIn("Copilot", self._detect(
            author_name="Dev", body="Potential fix for code scanning alert no. 5\n\n"
                                    "Co-authored-by: Copilot Autofix powered by AI "
                                    "<62310815+github-advanced-security[bot]@users.noreply.github.com>"))

    def test_copilot_autofix_display_name_detects_copilot(self):
        self.assertIn("Copilot", self._detect(
            author_name="Copilot Autofix powered by AI"))

    def test_philanthropic_domain_does_not_detect_claude(self):
        # "anthropic" appears inside other words. The domain patterns are
        # anchored by the .com / .ai suffix.
        self.assertEqual(self._detect(author_email="person88@example.org"), [])

    def test_cursor_agent_identity_detects_cursor(self):
        # Cursor's agent commits as "Cursor Agent <cursoragent@cursor.com>" and
        # adds no trailer of its own, and the identity is the only signal.
        self.assertIn("Cursor", self._detect(
            subject="docs: align frontend route CSV",
            author_name="Cursor Agent", author_email="cursoragent@cursor.com",
            committer_name="Cursor Agent", committer_email="cursoragent@cursor.com"))

    def test_cursor_s_agent_addresses_detect_cursor_and_the_domain_alone_does_not(self):
        """`Cursor Assistant <assistant@cursor.com>` is the identity of Cursor's agent in mflux
        and other repositories on GitHub. Reading the whole domain would credit Cursor with
        the commits of a person who works there."""
        self.assertIn("Cursor", self._detect(author_name="Cursor Assistant",
                                             author_email="assistant@cursor.com"))
        self.assertNotIn("Cursor", self._detect(author_name="Dev", author_email="someone@cursor.com"))

    def test_cursoragent_without_separator_detects_cursor(self):
        self.assertIn("Cursor", self._detect(author_name="cursoragent"))

    def test_gemini_cli_identity_detects_gemini(self):
        # Gemini CLI commits as "Gemini CLI <gemini-cli@example.com>", also
        # with no trailer.
        self.assertIn("Gemini", self._detect(
            subject="feat: add card rendering",
            author_name="Gemini CLI", author_email="gemini-cli@example.com",
            committer_name="Gemini CLI", committer_email="gemini-cli@example.com"))

    def test_gemini_cli_hyphenated_detects_gemini(self):
        self.assertIn("Gemini", self._detect(author_name="gemini-cli"))

    def test_an_identity_that_is_not_github_copilot_names_no_tool(self):
        """A Copilot identity heuristic that matched the word anywhere would credit Copilot with
        another product named Copilot, another project's GitHub App, a person at a company named
        for the word and a person's +copilot alias, as in commits of grpc/grpc in the October
        2026 collection that no other heuristic credits to Copilot."""
        for name, email in (("OneUptime Copilot", "copilot@oneuptime.com"),
                            ("person-61", "copilot@oneuptime.com"),
                            ("erigon-copilot[bot]",
                             "265817861+erigon-copilot[bot]@users.noreply.github.com"),
                            ("Max Stiles", "person173@example.org"),
                            ("person-53", "first184.last+copilot@example.com"),
                            ("A Person", "292387+copilot@users.noreply.github.com")):
            with self.subTest(name=name, email=email):
                self.assertEqual(self._detect(author_name=name, author_email=email,
                                              committer_name="GitHub",
                                              committer_email="noreply@github.com"), [])
                self.assertEqual(self._detect(author_name="GitHub",
                                              author_email="noreply@github.com",
                                              committer_name=name, committer_email=email), [])

    def test_github_s_copilot_identities_detect_copilot(self):
        """A name that begins with Copilot or GitHub Copilot, and the addresses of GitHub's
        three Copilot apps under any name."""
        for name, email in (("Copilot", "198982749+Copilot@users.noreply.github.com"),
                            ("\U0001F916 Copilot", "no-reply@github.com"),
                            ("GitHub Copilot CLI", "copilot@github.com"),
                            ("Copilot Autofix powered by AI", "dev@example.com"),
                            ("pureween", "223556219+Copilot@users.noreply.github.com"),
                            ("A Person", "175728472+Copilot@users.noreply.github.com")):
            with self.subTest(name=name, email=email):
                self.assertEqual(self._detect(author_name=name, author_email=email,
                                              committer_name="GitHub",
                                              committer_email="noreply@github.com"), ["Copilot"])
                self.assertEqual(self._detect(author_name="A Person", author_email="a@example.com",
                                              committer_name=name, committer_email=email),
                                 ["Copilot"])

    def test_a_disclosure_line_without_a_colon_or_with_by_or_assistance_from(self):
        """Disclosure lines of the October 2–3 collection in other forms: no colon after
        Assisted by, by where the heuristics have with, drafted, with assistance from, and a
        verb other than Implemented before with AI assistance."""
        for line, tool in (("\U0001F916 Assisted by Claude Code", "Claude"),
                           ("*\u270d\ufe0f Drafted by Claude Code*", "Claude"),
                           ("Generated with AI assistance (Claude).", "Claude"),
                           ("Prepared with AI assistance (Claude Code, Anthropic)", "Claude"),
                           ("(Written by Copilot)", "Copilot"),
                           ("Generated by GitHub Copilot, and manually adjusted.", "Copilot"),
                           ("Assisted by Cursor", "Cursor"),
                           ("> Written by cursor-grok-4.6 on Cursor", "Cursor"),
                           ("Implemented by Codex (gpt-5.5 low), reviewed by Claude.", "Codex"),
                           ("Developed with assistance from OpenAI Codex.", "Codex"),
                           ("This contribution was developed with AI assistance (Codex).", "Codex"),
                           ("Authored by Gemini CLI:", "Gemini")):
            with self.subTest(line=line):
                self.assertEqual(self._detect(subject="Fix the parser",
                                              body=f"Fix the parser\n\n{line}"), [tool])

    def test_a_disclosure_with_its_tools_on_the_next_line_of_a_wrapped_parenthesis(self):
        """dotnet/runtime b3c0988064f5 wraps oxc's disclosure inside the parenthesis, and the tool
        on the next line counts as the tool on the first does. A tool that only checked the
        change, as in dotnet/runtime f9725f177998, does not count, as a Reviewed-by trailer does
        not."""
        body = ("Fixes #136175\n\n> [!NOTE]\n> This PR was prepared with AI assistance (Anthropic Claude "
                "and OpenAI\nCodex), under my direction. I reviewed it before posting.")
        self.assertEqual(self._detect(subject="Accept the calls", body=body), ["Claude", "Codex"])
        body = ("Fixes #135990\n\n> [!NOTE]\n> This PR was prepared with AI assistance (Anthropic Claude, "
                "checked by\nOpenAI Codex) at my request. I reviewed it before opening it.")
        self.assertEqual(self._detect(subject="Keep the frame", body=body), ["Claude"])

    def test_a_disclosure_naming_claude_without_code_credits_claude(self):
        """The heuristic for a line that says a change was made with Claude matches Claude in
        every form, as the trailer rows do, and not Claude Code alone. The lines are from the
        October 2–3 collection."""
        for line in ("Created with assistance from Claude \U0001F916 <claude@anthropic.com>",
                     "Authored with Claude.", "Drafted with Claude Opus 4.8 (1M context).",
                     "[Co-Authored with Claude Opus 4.6]", "Generated with Claude"):
            with self.subTest(line=line):
                self.assertEqual(self._detect(subject="Fix the parser",
                                              body=f"Fix the parser\n\n{line}"), ["Claude"])
        # Another product of Anthropic's, a model in another tool's parentheses, and a model
        # that another agent ran.
        for line in ("Generated with Claude Desktop",
                     "Generated with GitHub Copilot (claude-sonnet-4.6)",
                     "Generated with Claude Opus 4.5 in OpenCode"):
            with self.subTest(line=line):
                self.assertNotIn("Claude", self._detect(subject="Fix the parser",
                                                        body=f"Fix the parser\n\n{line}"))

    def test_a_labeled_disclosure_credits_the_tool_it_names(self):
        """Lines that begin with AI disclosure, AI assistance, AI usage or Disclosure and
        name a tool, from the October 2–3 collection."""
        for line, tools in (("AI disclosure: Partially written with Codex and GPT 5.5.", ["Codex"]),
                            ("AI assistance: used Cursor; I reviewed and understand the change.", ["Cursor"]),
                            ("AI usage: GitHub Copilot CLI assisted with implementation and validation.", ["Copilot"]),
                            ("*Disclosure: the code was written by AI (Claude); reviewed and tested by me.*", ["Claude"]),
                            ("**Generative AI disclosure:** Developed with AI assistance (Claude Code)", ["Claude"]),
                            ("AI disclosure: used Antigravity", ["Gemini"]),
                            ("AI disclosure: prepared with GitHub Copilot (claude-sonnet-4.6)", ["Copilot"]),
                            ("AI disclosure: this change was mainly made via AI (Copilot + Claude Opus 4.6)", ["Copilot"]),
                            ("AI-assisted: drafted by Claude, verified locally, reviewed by Codex.", ["Claude"]),
                            ("AI-assisted: yes (claude-opus-4)", ["Claude"]),
                            ("AI-assisted: Changes were prepared with GitHub Copilot (GPT-5.3-Codex), then reviewed", ["Copilot"]),
                            ("AI-assisted: OpenCode (claude-sonnet-4.6)", ["OpenCode"]),
                            ("AI-assisted: opencode (github-copilot/gpt-5)", ["OpenCode"])):
            with self.subTest(line=line):
                self.assertEqual(self._detect(subject="Fix the parser",
                                              body=f"Fix the parser\n\n{line}"), tools)
        for subject, body in (("ai: update copilot instructions", ""),
                              ("Fix the parser", "Fix the parser\n\nAI assistance: Claude Sonnet 4.5 in pi agent"),
                              ("Fix the parser", "Fix the parser\n\nAI disclosure: I did not use Copilot."),
                              ("Fix the parser", "Fix the parser\n\nAI disclosure: none")):
            with self.subTest(subject=subject, body=body):
                self.assertEqual(self._detect(subject=subject, body=body), [])

    def test_a_generated_description_or_review_credits_no_tool(self):
        """A pull request description or review that a tool wrote, as commits of the October
        2026 collection contain them, does not show who wrote the change."""
        for line in ("> This pull request description was generated with GitHub Copilot.",
                     "> This PR description was generated with GitHub Copilot.",
                     "> <sup>Written by [Cursor Bugbot](https://cursor.com/dashboard?tab=bugbot) for commit c775eb3</sup>",
                     "> <sup>Reviewed by [Cursor Bugbot](https://cursor.com/bugbot) for commit a7467e5</sup>"):
            with self.subTest(line=line):
                self.assertEqual(self._detect(subject="Fix the parser",
                                              body=f"Fix the parser\n\n{line}"), [])

    def test_copilot_s_pull_request_summary_credits_no_tool(self):
        """Copilot for pull requests writes a summary of a pull request, not its code."""
        for line in ("Generated by Copilot at 4a38786",
                     "### <samp>\U0001F916 Generated by Copilot at 4a38786</samp>"):
            with self.subTest(line=line):
                self.assertEqual(self._detect(subject="Fix the parser",
                                              body=f"Fix the parser\n\n{line}"), [])

    def test_precursor_does_not_detect_cursor(self):
        # The Cursor patterns must not match a word that merely contains
        # "cursor".
        self.assertEqual(self._detect(author_email="precursor@example.com"), [])

    def test_a_word_that_only_contains_a_tool_name_is_no_identity(self):
        """The word boundaries of the identity heuristics that have them: dropping them from
        \\bcursor[\\s_\\-]?agent or \\bgemini[\\s_\\-]?cli\\b, or the end of a name from the
        Copilot name heuristic, fails this test."""
        for name, email in (("copilotkit-bot", "ops@copilotkit.ai"),
                            ("precursor-agent", "build@example.com"),
                            ("Gemini Mustermann", "person134@example.com"),
                            ("mygemini-cli", "dev@example.com")):
            with self.subTest(name=name):
                self.assertEqual(self._detect(author_name=name, author_email=email), [])

    def test_new_identities_are_skipped_when_check_author_is_false(self):
        for name, email in (("Cursor Agent", "cursoragent@cursor.com"),
                            ("Gemini CLI", "gemini-cli@example.com")):
            with self.subTest(name):
                self.assertEqual(
                    self._detect(author_name=name, author_email=email,
                                 check_author=False), [])

