    def test_co_authored_by_copilot_detects_copilot(self):
        body = "Fix\n\nCo-authored-by: GitHub Copilot <copilot@github.com>"
        self.assertIn("Copilot", self._detect(body=body))

    def test_co_authored_by_copilot_bare_detects_copilot(self):
        body = "Fix\n\nco-authored-by: copilot"
        self.assertIn("Copilot", self._detect(body=body))

    def test_from_copilot_branch_detects_copilot(self):
        self.assertIn("Copilot", self._detect(
            subject="Merge pull request #1 from octo/copilot/fix-auth-bug"
        ))

    def test_a_merge_of_a_copilot_branch_is_this_commits_own_line(self):
        """A squash lists its pull request's commits, and a prefix or a bracket may come first. Each
        is the commit's own merge of the branch."""
        for subject, body in (
                ("Add Teak extension (#25350)",
                 "- fix lists\n- Merge pull request #4 from ewilderj/copilot/fix-b8b95185"),
                ("docs: Merge pull request #22528 from unoplatform/copilot/sub-pr-22527", ""),
                ("[skip actions] Merge pull request #673 from doudar/copilot/fix-672", ""),
                ("Merge pull request dotnet/templating#9592 from dotnet/copilot/revert", "")):
            with self.subTest(subject=subject):
                self.assertIn("Copilot", self._detect(subject=subject, body=body))

    def test_a_merge_of_a_copilot_branch_that_another_text_quotes_is_no_credit(self):
        """A dependency update that quotes the upstream release notes, a revert of the merge, a path
        under .github/copilot/, the line of another commit in a release commit, and the merge tool of
        apache/zeppelin are no merge of a Copilot branch by the commit itself. All heads of pull
        request 5208 of apache/zeppelin carry a co-author line of Claude, and Copilot only reviewed."""
        for subject, body in (
                ("build(deps): bump github/codeql-action from 4.32.0 to 4.32.2 (#699)",
                 "<li>Merge pull request #3 from github/copilot/fix-github-actions-workflow-again</li>"),
                ('Revert "Merge pull request #394 from chrxh/copilot/adapt-description-converter"', ""),
                ("Move Copilot rules from .github/copilot/ to .github/instructions/", ""),
                ("Bump package versions (#1196)", "- f4727f41684c1d727ad0401501bec3a37215089d: Merge pull "
                                                  "request #1176 from meziantou/copilot/sub-pr-1172 Fix CI"),
                ("[ZEPPELIN-6321] Fix npm audit issues", "Closes #5208 from jongyoul/copilot/fix-npm")):
            with self.subTest(subject=subject):
                self.assertNotIn("Copilot", self._detect(subject=subject, body=body))

    def test_a_revert_takes_no_credit_from_the_subject_it_quotes(self):
        """git writes a revert's subject as `Revert "<the reverted commit's subject>"`, and the
        credit there is therefore the reverted commit's. The revert's own body still counts."""
        self.assertEqual(self._detect(subject='Revert "Co-authored-by: Copilot"',
                                      body="This reverts commit 9e9cbf3a52."), [])
        self.assertEqual(self._detect(
            subject='Revert "ui: assisted by claude (in debugging and tests)"',
            body="This reverts commit dbdaece23d."), [])
        self.assertEqual(self._detect(
            subject='Revert "Add a cache"',
            body="This reverts commit abc.\n\nCo-authored-by: Claude <noreply@anthropic.com>"),
            ["Claude"])

    def test_an_unticked_box_of_a_task_list_takes_no_credit(self):
        """`- [ ]` is a task not done, as in the template box of chainsafe/lodestar fd4f342a40."""
        for marker in ("- [ ]", "* [ ]", "1. [ ]", "  - [ ]"):
            with self.subTest(marker=marker):
                self.assertEqual(self._detect(
                    body=f"Checklist\n\n{marker} created with the help of Claude"), [])
        self.assertEqual(self._detect(body="Checklist\n\n- [x] created with the help of Claude"),
                         ["Claude"])

    def test_a_person_named_claude_is_no_co_author_claude(self):
        """A person with the first name Claude commits under that name to apache/beam, at an
        address of google.com. The rows test the domain of a bare Claude rather than the person's
        address, and Claude Code's name with another word stays a credit at that domain."""
        for address in ("person-a@google.com", "claude.doe@google.com"):
            with self.subTest(address=address):
                self.assertNotIn("Claude", self._detect(
                    body=f"Fix indent\n\nCo-authored-by: Claude <{address}>"))
        for line in ("Co-authored-by: Claude <noreply@anthropic.com>",
                     "Co-authored-by: Claude <svc-devxp-claude@slack-corp.com>",
                     "Co-authored-by: Claude Code <person-a@google.com>"):
            with self.subTest(line=line):
                self.assertIn("Claude", self._detect(body=f"Fix\n\n{line}"))

    def test_the_person_with_the_login_copilot_is_no_copilot(self):
        """GitHub's API gives the login Copilot to three apps and copilot to account 292387."""
        self.assertEqual(self._detect(
            body="Fix\n\nCo-authored-by: Jane <292387+copilot@users.noreply.github.com>"), [])
        self.assertIn("Copilot", self._detect(
            body="Fix\n\nCo-authored-by: Jane <223556219+Copilot@users.noreply.github.com>"))

