    def test_a_gemini_credit_naming_no_product_is_not_gemini(self):
        """Google documents no commit trailer for Gemini CLI, and Gemini is also its chat app:
        apache/impala writes `Assisted-by: Gemini <https://gemini.google.com>`. Such a credit is
        recorded as Gemini (unspecified) among the tools outside the six."""
        for body in ("Fix\n\nCo-authored-by: Gemini <noreply@google.com>",
                     "Fix\n\nAssisted-by: Gemini <https://gemini.google.com>",
                     "Fix\n\nGenerated-by: Gemini Pro",
                     "Fix\n\nThe bulk of this PR was generated by gemini"):
            with self.subTest(body=body):
                self.assertEqual(self._detect(body=body), [])
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(
                    "", "", "", "", "", body), ["Gemini (unspecified)"])

    def test_a_gemini_credit_naming_the_cli_or_code_assist_is_gemini_alone(self):
        for body in ("Fix\n\nCo-authored-by: gemini-code-assist[bot] "
                     "<176961590+gemini-code-assist[bot]@users.noreply.github.com>",
                     "Fix\n\nGenerated-by: Google Gemini 2.5 Pro + Gemini Cli",
                     "This commit was generated by Gemini CLI."):
            with self.subTest(body=body):
                self.assertEqual(self._detect(body=body), ["Gemini"])
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(
                    "", "", "", "", "", body), [])

    def test_gemini_run_by_copilot_codex_or_cursor_is_that_tools_alone(self):
        """As for Claude: the model is Gemini and the tool that ran it is named after via or in
        parentheses, a line of the collection started on 2026-09-24."""
        body = "Fix\n\nAssisted-by: gemini-3-flash-preview (via Cursor)"
        self.assertEqual(self._detect(body=body), ["Cursor"])
        self.assertEqual(_mod.detect_other_ai_tools_in_fields("", "", "", "", "", body), [])

    def test_a_person_whose_username_begins_with_gemini_is_not_gemini(self):
        """The heuristic's note states that its word boundary is there for these two people,
        who would otherwise be classified as Gemini."""
        for trailer in ("Co-authored-by: Geminidoe <geminidoe@users.noreply.github.com>",
                        "Co-authored-by: Geminidoe <geminidoe@users.noreply.github.com>"):
            with self.subTest(trailer=trailer):
                self.assertEqual(self._detect(body="Fix\n\n" + trailer), [])

