COPILOT_CO_AUTHORED = r"co-authored-by:(?![^\n]*\bcopilot[ \t]+fallback\b)\s*(?:github\s+)?copilot"
CODEX_ASSISTED = PATTERN_OF["codex-trailer-01"]
CODEX_CO_AUTHORED = r"co-authored-by:\s*(?:openai\s+)?codex\b(?!-(?:yv|reset\.com)\b)"
CURSOR_ASSISTED = PATTERN_OF["cursor-trailer-01"]
# The heuristics of a tool named first in an Authored-by, Created-by or Made-with line, read on
