CLAUDE_AUTHORED = PATTERN_OF["claude-trailer-13"]
CODEX_AUTHORED = r"(?:authored-by|made-with):\s*(?:openai\s+)?codex\b"
CURSOR_AUTHORED = r"authored-by:\s*cursor\b"
GEMINI_NAMED = PATTERN_OF["gemini-trailer-01"]
