CURSOR_CO_DEVELOPED = '(?:co-developed|signed-off)-by:\\s*(?:cursor|(?:anthropic[ \\t]+)?claude[^\\n]*(?:\\bvia\\s+cursor\\b|\\((?:via\\s+)?cursor\\b))'
CODEX_CO_DEVELOPED = '(?:co-developed|signed-off)-by:\\s*(?:(?:openai\\s+)?codex|(?:anthropic[ \\t]+)?claude[^\\n]*(?:\\bvia\\s+(?:openai\\s+)?codex\\b|\\((?:openai\\s+)?codex(?:\\s+cli)?\\)))'
CLAUDE_ASSISTED_BY_LINE = PATTERN_OF["claude-full-body-07"]
COPILOT_ASSISTED_BY_LINE = PATTERN_OF["copilot-full-body-07"]
CURSOR_ASSISTED_BY_LINE = PATTERN_OF["cursor-full-body-06"]
CODEX_ASSISTED_BY_LINE = PATTERN_OF["codex-full-body-06"]
GEMINI_ASSISTED_BY_LINE = PATTERN_OF["gemini-full-body-05"]
CLAUDE_DISCLOSURE = PATTERN_OF["claude-full-body-08"]
CODEX_DISCLOSURE = PATTERN_OF["codex-full-body-07"]
COPILOT_DISCLOSURE = PATTERN_OF["copilot-full-body-10"]
CURSOR_DISCLOSURE = PATTERN_OF["cursor-full-body-07"]
GEMINI_DISCLOSURE = PATTERN_OF["gemini-full-body-04"]
