class TestEveryRuleHasACase(unittest.TestCase):
    """Each heuristic has a commit that it matches, checked against all the rows that the
    commit matches rather than against the tool alone, so that a heuristic that another heuristic of
    the same tool also covers cannot stop matching without a failure."""

    @staticmethod
    def _fields(case: dict) -> tuple:
        return (*case.get("author", HUMAN), *case.get("committer", HUMAN),
                case.get("subject", "chore: update"), case.get("body", ""))

    def test_every_row_of_the_heuristics_has_a_case(self):
        # A row added without a case fails here, and so does a case left for a removed row.
        self.assertEqual(sorted(r["pattern"] for r in AI_COMMIT_PATTERNS), sorted(RULE_CASES))

    def test_each_case_matches_its_own_row_and_the_ones_it_names(self):
        for pattern, (tool, case, also) in RULE_CASES.items():
            with self.subTest(pattern=pattern):
                ids = _mod.matched_rules_in_fields(*self._fields(case))
                matched = {PATTERN_OF[n] for n in ids}
                self.assertEqual(matched, {pattern, *also})

    def test_each_case_is_read_as_its_tool_and_no_other(self):
        for pattern, (tool, case, _) in RULE_CASES.items():
            with self.subTest(pattern=pattern):
                self.assertEqual(detect_ai_tools_in_fields(*self._fields(case)), [tool])


class TestTheRequiredLiterals(unittest.TestCase):
    """A heuristic does not run on a text that lacks a literal that a match has to contain, which
    must never change what the heuristics read."""

    def test_what_a_match_has_to_contain_counts(self):
        cases = {
            # A literal, whatever its case in the pattern.
            r"Co-Authored-By": {frozenset({"co-authored-by"})},
            # Each part that a match has to contain gives a set of its own.
            r"assisted-by:[ \t]*composer": {frozenset({"assisted-by:"}), frozenset({"composer"})},
            # An alternation contributes the literals of all its alternatives.
            r"(?:claude|gemini)-generated": {frozenset({"claude", "gemini"}),
                                             frozenset({"-generated"})},
            # A group, and a part that repeats at least once.
            r"(agent)(?:bot)+": {frozenset({"agent"}), frozenset({"bot"})},
        }
        for pattern, expected in cases.items():
            with self.subTest(pattern=pattern):
                self.assertEqual(set(_heuristics.required_literals(pattern)), expected)

    def test_what_a_match_can_leave_out_does_not_count(self):
        cases = {
            "an optional part": r"(?:claude)?code",
            "a repeat that may be empty": r"(?:claude)*code",
            "a lookahead": r"(?=claude)code",
            "a negative lookbehind": r"(?<!claude )code",
            "an alternative without a literal": r"(?:claude|\w+)code",
            "an empty alternative": r"(?:claude|)code",
            "a class": r"[cl]+code",
        }
        for name, pattern in cases.items():
            with self.subTest(name):
                self.assertEqual(_heuristics.required_literals(pattern), (frozenset({"code"}),))

    def test_a_character_outside_ascii_ends_a_literal(self):
        self.assertEqual(set(_heuristics.required_literals("agent·bot")),
                         {frozenset({"agent"}), frozenset({"bot"})})

    def test_a_literal_of_one_character_does_not_count(self):
        self.assertEqual(_heuristics.required_literals(r"<\w+@"), ())

    def test_a_character_that_a_pattern_matches_with_a_letter_is_lowered_to_it(self):
        # Every character that a pattern which ignores case matches with an ASCII letter, however
        # `str.lower` treats it, or a heuristic would not run on a text that it matches.
        letters = re.compile("[a-z]", re.IGNORECASE)
        for point in range(sys.maxunicode + 1):
            character = chr(point)
            if letters.fullmatch(character):
                letter = next(c for c in string.ascii_lowercase
                              if re.fullmatch(c, character, re.IGNORECASE))
                with self.subTest(point=hex(point)):
                    self.assertEqual(_heuristics.lowered_for_literals(character), letter)

    def test_a_credit_in_a_case_variant_of_its_literal_is_read(self):
        # U+0131, the dotless i, which a pattern that ignores case matches with i, and which
        # `str.lower` leaves alone.
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "chore: update",
                                                   "Assisted-by: Cop\u0131lot"), ["Copilot"])

    def test_the_check_changes_no_result_of_any_case(self):
        # The heuristics without the check, over the commit of each row of the six tools and over
        # the lines of the tools outside the six.
        commits = [TestEveryRuleHasACase._fields(case) for _, case, _ in RULE_CASES.values()]
        commits += [(*HUMAN, *HUMAN, "chore: update", line)
                    for _, _, line in TestTheOtherToolsOfTheSeptemberCollection.READ]
        for fields in commits:
            trailer, full_body = _mod.scope_texts(fields[4], fields[5])
            author = " ".join(f for f in fields[:4] if f)
            for compiled, checked in ((_mod._COMPILED_PATTERNS, _mod._CHECKED_PATTERNS),
                                      (_mod._OTHER_COMPILED_PATTERNS, _mod._OTHER_CHECKED_PATTERNS)):
                with self.subTest(body=fields[5]):
                    self.assertEqual(
                        _mod._detect(checked, *fields, True),
                        [tool for tool, by_author, by_trailer, by_body in compiled
                         if any(p.search(author) for p in by_author)
                         or any(p.search(trailer) for p in by_trailer)
                         or any(p.search(full_body) for p in by_body)])

    def test_every_row_has_a_required_literal(self):
        # A row without one runs on every commit, which is allowed but should be a decision.
        for row in [*AI_COMMIT_PATTERNS, *_mod.OTHER_AI_COMMIT_PATTERNS]:
            with self.subTest(row=row["id"]):
                self.assertTrue(_heuristics.required_literals(row["pattern"]))


class TestEveryPatternMatchesInLinearTime(unittest.TestCase):
    """No pattern of either heuristics file may take time exponential in a message's length,
    or a Dependabot list on one line, such as the subject of apache/tomee 0ffc2bcc93bb, would
    stall a reclassification."""

    # The subject of tomee's commit begins "--- updated-dependencies: - dependency-name:
    # org.apache.tomcat:tomcat-catalina   dependency-type: direct:production   update-type:
    # version-update:semver-patch - dependency-name: ...". Thirty entries is 2^150 ways
    # for a pattern that can split each run of spaces two ways, and milliseconds for a
    # pattern that cannot.
    DEPENDABOT = ("--- updated-dependencies: " + "- dependency-name: org.apache.tomcat:tomcat-api"
                  "   dependency-type: direct:production   update-type: version-update:semver-patch "
                  * 30 + "...")
    TEXTS = [DEPENDABOT, DEPENDABOT.replace(" ", "\t"), "a: " * 400, "[x] " * 400,
             "- " * 2000, " " * 20000, "co-authored-by: " * 300, "<a@b.c> " * 1000,
             "x/" * 5000, "claude " * 2000, "generated with " * 1000]

    def test_every_pattern_reads_long_messages_in_seconds(self):
        # In a process of its own, because a stalled match blocks the interpreter, and only a
        # process can be stopped. The program prints each heuristic before matching it, so that
        # the last line names the heuristic that stalled.
        program = ("import json, sys\n"
                   "from agentcontext import commits\n"
                   "texts = json.load(sys.stdin)\n"
                   "for heuristic, _, _, _, compiled in (*commits._INDEXED_PATTERNS,\n"
                   "                                     *commits._OTHER_INDEXED_PATTERNS):\n"
                   "    print(heuristic, flush=True)\n"
                   "    for text in texts:\n"
                   "        compiled.search(text)\n"
                   "        compiled.search(text + '\\n' + text)\n"
                   "print('all', flush=True)\n")
        try:
            proc = subprocess.run([sys.executable, "-c", program], input=json.dumps(self.TEXTS),
                                  capture_output=True, text=True, cwd=str(REPO_ROOT), timeout=60)
        except subprocess.TimeoutExpired as stopped:
            output = stopped.stdout or ""
            output = output.decode() if isinstance(output, bytes) else output
            self.fail(f"{output.split()[-1] if output.split() else 'the first heuristic'} "
                      f"did not finish within 60 seconds")
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertEqual(proc.stdout.split()[-1], "all")


