        ("Update oxen-rust/cli-test/tests/helpers.py",
         "Add default timeout to `run_command` helper.\n\n" + CODERABBIT, "CodeRabbit:reviewer"),
        ("Update src/UI/Components/MobileUI/MobileUI.js", DEVIN, "Devin:reviewer"),
