    def test_each_line_credits_the_tool_that_it_names(self):
        for line, tool in self.READ:
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "fix: x", "Summary\n\n" + line)
                self.assertEqual(detect_ai_tools_in_fields(*fields), [tool])
                self.assertEqual(_mod.attributions_in_fields(*fields), f"{tool}:convention")

