class TestPisAddresses(unittest.TestCase):
    """The pi extension pi-co-authored-by writes its co-author line at noreply@pi.dev before a
    Generated-By line, as brechtm/rinohtype 92b51051adc0 has them, which credits pi as standard.
    A line at pi's address alone, which repositories' instructions require, as in Shopify/cli
    714c7693f590, credits pi as a convention."""

    def test_the_extension_s_lines_are_standard_and_a_line_alone_is_a_convention(self):
        cases = (("Co-Authored-By: DeepSeek V4.1 Flash <noreply@pi.dev>\nGenerated-By: pi 0.85.1",
                  "pi:standard"),
                 ("Co-authored-by: AI <noreply@pi.dev>", "pi:convention"),
                 ("Assisted-by: claude-opus-5-5 <pi@earendil.works>", "pi:convention"))
        for body, attributions in cases:
            with self.subTest(body=body):
                self.assertEqual(_mod.other_attributions_in_fields(*HUMAN, *HUMAN, "fix: x", body),
                                 attributions)


class TestMadeWithPiCreditsPi(unittest.TestCase):
    """OpenAPITools/openapi-generator 7fb0f556191c and 502c943a3450 end with `Made-With: pi`,
    and neither commit credits a tool in another line. pi-trailer-01 reads pi after `Made-with:`
    as it reads pi after `Assisted-by:`, as a convention, because pi's code writes no such line.
    The messages are copied from the commit logs of the run that started on 2026-10-23,
    shortened."""

    COMMITS = {
        "https://github.com/OpenAPITools/openapi-generator/commit/7fb0f556191c0d8292f655e65660928d481db9fa": (
            "[scala-sttp4] Omit optional fields set to None instead of serializing null (circe) "
            "(#24362)",
            "The circe branch of scala-sttp4 uses plain deriveEncoder, which serializes\n"
            "Option None as JSON null.\n\nFixes #24360\n\nMade-With: pi"),
        "https://github.com/OpenAPITools/openapi-generator/commit/502c943a34507660926817f0889ad95d7206e93b": (
            "[scala-sttp4] Fix enum operation parameters: type import and wire-value toString "
            "(#24346)",
            "Enums used as operation parameters in the scala-sttp4 generator are broken\n"
            "in two ways:\n\nCovered by Sttp4CodegenTest#verifyEnumParameterImportAndWireValues; "
            "sttp4\npetstore samples regenerated.\n\nMade-With: pi"),
    }

    def test_each_commit_credits_pi_as_a_convention_and_none_of_the_six_tools(self):
        evidence = next(r["evidence"] for r in _mod.OTHER_AI_COMMIT_PATTERNS
                        if r["id"] == "pi-trailer-01").split()
        for url, (subject, body) in self.COMMITS.items():
            with self.subTest(url=url):
                self.assertIn(url, evidence)
                fields = ("Mark Poe", "person278@example.com", "GitHub", "noreply@github.com",
                          subject, body)
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), ["pi-trailer-01"])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "pi:convention")
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])


class TestPisOwnNamesCreditPi(unittest.TestCase):
    """pi names itself Pi coding agent (the description of the flake.nix of earendil-works/pi at
    d57c2d21916e), its package is `@earendil-works/pi-coding-agent`, and its site is pi.dev, which
    gives the command `npm install -g --ignore-scripts @earendil-works/pi-coding-agent`.
    elastic/elasticsearch-js f1736cbb014f credits `Pi Coding Agent (claude-opus-5-5)`, and
    OpenVidu/openvidu ba72e6b9693b credits `pi - Hosted locally - Qwen 3.8 Flash Next`.
    pi-trailer-01 reads these names, a hyphen between spaces and `with` after pi, first in the
    value of each token that it reads, and the names later in the value too, as in
    openshift/kube-compare fac46301af7c, as a convention, because pi's code writes no such line.
    The Claude rows skip a line with pi.dev, so that the commit credits pi and not Claude.
    The messages come from GitHub's API, shortened."""

    COMMITS = {
        "https://github.com/elastic/elasticsearch-js/commit/f1736cbb014f4e81430485f185866659c2297a0e": (
            ("Ida Sixpack", "first169.last@example.org", "GitHub", "noreply@github.com"),
            "Add maxRequestBytes option to bulk helper (#3479)",
            "* Add maxRequestBytes option to bulk helper\n\nCloses #3470\n\n"
            "Assisted-by: Pi Coding Agent (claude-sonnet-5-5)\n\n"
            "* Re-arm bulk flush timer after a maxRequestBytes flush\n\n"
            "Assisted-by: Pi Coding Agent (claude-opus-5-5)"),
        "https://github.com/OpenVidu/openvidu/commit/ba72e6b9693b6ce2224e10d17d3c680cefbc0b26": (
            ("Eve Q. Public", "first98.last@example.com", "GitHub", "noreply@github.com"),
            "Merge pull request #915 from OpenVidu/chore/update-openvidu-actions-v1.0.24",
            "\n\nAssisted-by: pi - Hosted locally - Qwen 3.8 Flash Next"),
        "https://github.com/openshift/kube-compare/commit/fac46301af7cd50bbe71064a2f0dd2a1b2f8bfc5": (
            ("Eve Public", "person170@example.com", "Eve Public", "person170@example.com"),
            "Add Helm-compatible include template function",
            "Add the \"include\" template function, matching Helm's semantics.\n\n"
            "Assisted-by: Claude Opus 4.6 and pi.dev"),
    }

    # The lines that the unmatched attributions of the collection of 2026-10-26 listed before
    # pi-trailer-01 read them, each naming pi first
    UNMATCHED = ("assisted-by: pi - hosted locally - qwen 3.8 flash next",
                 "assisted-by: pi coding agent:openai", "assisted-by: pi-coding-agent",
                 "assisted-by: pi-coding-agent:openai chatgpt", "assisted-by: pi.dev",
                 "co-authored-by: pi coding agent", "co-authored-by: pi with gpt-5.3-codex")

    def test_each_commit_credits_pi_as_a_convention_and_none_of_the_six_tools(self):
        evidence = next(r["evidence"] for r in _mod.OTHER_AI_COMMIT_PATTERNS
                        if r["id"] == "pi-trailer-01").split()
        for url, (identities, subject, body) in self.COMMITS.items():
            with self.subTest(url=url):
                self.assertIn(url, evidence)
                fields = (*identities, subject, body)
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), ["pi-trailer-01"])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "pi:convention")
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])

    def test_each_name_of_pi_first_in_the_value_of_each_token_credits_pi(self):
        names = ("Pi Coding Agent", "pi coding agent", "pi-coding-agent", "pi.dev")
        values = [f"{name}{after}" for name in names
                  for after in ("", ":openai", " (claude-opus-5-5)", " (Claude Opus 5.5)")]
        values += ["pi - Hosted locally - Qwen 3.8 Flash Next", "pi with gpt-5.3-codex"]
        lines = [f"{token}: {value}" for token in ("Assisted-by", "Co-authored-by", "Generated-by", "Made-with")
                 for value in values] + list(self.UNMATCHED)
        for line in lines:
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "fix: x", "Summary\n\n" + line)
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "pi:convention")
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])

    def test_a_name_after_pi_credits_no_tool(self):
        """The unmatched attributions of 2026-10-26 list people and accounts with a name that
        starts with pi, which no row reads."""
        for line in ("co-authored-by: pi doe", "co-authored-by: pi roe",
                     "co-authored-by: pi-dal", "co-authored-by: pi-gitea",
                     "co-authored-by: pi-skrydalewicz-ext", "co-authored-by: pi-squared-studio"):
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "fix: x", "Summary\n\n" + line)
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])


