    def test_each_commit_credits_pi_as_a_convention_and_none_of_the_six_tools(self):
        evidence = {r["id"]: r["evidence"].split() for r in _mod.OTHER_AI_COMMIT_PATTERNS}
        for url, (identities, row, subject, body) in self.COMMITS.items():
            with self.subTest(url=url):
                self.assertIn(url, evidence[row])
                fields = (*identities, subject, body)
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields),
                                 [row, *self.ALSO_READ_BY.get(url, ())])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "pi:convention")
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])

