class TestTheOriginalPromptOfCopilotsCloudAgentCreditsNothing(unittest.TestCase):
    """Copilot's cloud agent quotes the issue and the comments on it in a `<details>` block with
    the summary `Original prompt`, and a squash merge copies the block into the commit. The comment
    of microsoft/onnxruntime 616a4dfc1434 that this message shortens names the issue and no change,
    and the commit credits Copilot through its co-author line alone."""

    COMMENT = ("> <comment_new><author>@person</author><body>\n"
               "> Wow - this is an issue I asked copilot to create. It does a perfect\n"
               "job.</body></comment_new>\n")
    AGENT = "Co-authored-by: copilot-swe-agent[bot] <198982749+Copilot@users.noreply.github.com>"
    BLOCK = ("<!-- START COPILOT ORIGINAL PROMPT -->\n\n\n\n<details>\n\n"
             "<summary>Original prompt</summary>\n\n> \n> ----\n> \n"
             "> ## Comments on the Issue (you are @copilot in this section)\n> \n> <comments>\n"
             + COMMENT + "> </comments>\n> \n\n\n</details>\n\n\n\n")
    BODY = f"### Description\n\nFixes a check.\n\n{BLOCK}- Fixes #27450\n\n---------\n\n{AGENT}"

    def test_a_comment_in_the_block_credits_nothing(self):
        self.assertEqual(_mod.matched_rules_in_fields(*HUMAN, *HUMAN, "fix: a check", self.BODY),
                         ["copilot-trailer-02", "copilot-trailer-04", "copilot-trailer-05"])
        self.assertEqual(_mod.attributions_in_fields(*HUMAN, *HUMAN, "fix: a check", self.BODY),
                         "Copilot:standard")

    def test_the_same_comment_outside_the_block_stays_read(self):
        """A squash merge keeps a quote at the start of a line for the disclosure of a pull
        request, so that the block is what separates the comment."""
        self.assertIn("copilot-full-body-41", _mod.matched_rules_in_fields(
            *HUMAN, *HUMAN, "fix: a check", self.COMMENT))

    def test_the_block_keeps_the_lines_of_the_message(self):
        self.assertEqual(_mod._own_lines(self.BODY).count("\n"), self.BODY.count("\n"))

    def test_a_block_without_a_closing_line_keeps_the_trailer_below_it(self):
        """Azure/data-api-builder 4c26d602f520 has no closing line, and its co-author line follows
        the block directly."""
        body = f"<details>\n\n<summary>Original prompt</summary>\n\n> Fix it.\n\n{self.AGENT}"
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "fix: a check", body), ["Copilot"])

    def test_another_block_and_a_line_after_the_block_stay_read(self):
        other = "<details>\n\n<summary>Notes</summary>\n\nI asked Copilot to fix the tests.\n\n</details>"
        below = f"{self.BLOCK}I asked Copilot to fix the tests."
        for body in (other, below):
            with self.subTest(body=body):
                self.assertIn("copilot-full-body-41",
                              _mod.matched_rules_in_fields(*HUMAN, *HUMAN, "fix: a check", body))


class TestTheChromiumCommitsThatBraveQuotesCreditNoTool(unittest.TestCase):
    """brave/brave-core quotes the commits of Chromium that a change follows below a line
    `Chromium changes:`, in the form of `git log`, or `Chromium change:` above one quoted commit, as
    4b67ac68ac97 does. A credit there belongs to the commit of Chromium, and the commit of Brave
    changes only Brave's own files. The messages are 6e74e53c4e22, 3a5bfd1e8dc8, c312b9537cbe and
    4b67ac68ac97, shortened, with fictional names."""

    @staticmethod
    def _chromium(*lines: str) -> str:
        indented = "\n".join(f"    {line}" if line else "" for line in lines)
        return ("Chromium changes:\nhttps://chromium.googlesource.com/chromium/src/+/57a7dfb\n\n"
                "commit 57a7dfb4e2645b9c62d3a005436c815f4314b5e6\n"
                "Author: Chromium Doe <doe@chromium.org>\n"
                "Date:   Tue Apr 7 01:29:42 2026 -0700\n\n"
                f"{indented}\n")

    def test_a_line_of_the_quoted_commit_credits_no_tool(self):
        for subject, body in (
                ("[cr149] IWYU for `base/logging.h`",
                 self._chromium("Remove base/logging.h include from validation_errors.h", "",
                                "gemini-cli was used to quickly prototype some ideas as well as implement",
                                "the overall CL, with some manual followups to improve naming.")),
                ("[cr156] Fix stale page state crash on extension-overridden NTP restore",
                 self._chromium("Keep rewritten URLs when restoring PageState", "",
                                "Co-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>")),
                ("[cr147] `kPrefetchScheduler` deleted",
                 self._chromium("PrefetchScheduler: Remove feature flag and unused code", "",
                                "Co-Authored-By: Gemini <noreply@google.com>"))):
            with self.subTest(subject=subject):
                fields = (*HUMAN, *HUMAN, subject, body)
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), [])

    def test_a_line_of_a_commit_quoted_below_the_singular_credits_no_tool(self):
        """brave/brave-core 4b67ac68ac97 writes `Chromium change:` in the singular above the one
        commit of Chromium that it quotes, with `AI-Model: antigravity` among the trailers of that
        commit. The message is shortened, with a fictional name and a credit that a row reads."""
        body = ("Chromium change:\n"
                "https://source.chromium.org/chromium/chromium/src/+/9ef798fd0337dd7b74b00f8d0ecc86192e0c24ea\n\n"
                "commit 9ef798fd0337dd7b74b00f8d0ecc86192e0c24ea\n"
                "Author: Chromium Doe <doe@chromium.org>\n"
                "Date:   Thu Jun 4 09:36:25 2026 -0700\n\n"
                "    variations: use crypto::sign::Verify\n\n"
                "    AI-Model: antigravity\n"
                "    Co-Authored-By: Gemini <noreply@google.com>\n"
                "    Bug: 406190025\n")
        fields = (*HUMAN, *HUMAN, "[cr151] variations: use crypto::sign::Verify", body)
        self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
        self.assertEqual(_mod.matched_other_rules_in_fields(*fields), [])
        self.assertNotIn("AI-Model", _mod._own_lines(body))

    def test_each_quoted_commit_is_left_empty_and_the_lines_keep_their_place(self):
        body = ("Chromium changes:\n\ncommit 57a7dfb\nAuthor: A <a@b>\nDate:   Tue\n\n    One\n\n"
                "commit 3b7459b\nAuthor: A <a@b>\nDate:   Wed\n\n    Co-Authored-By: Gemini <noreply@google.com>\n")
        own = _mod._own_lines(body)
        self.assertEqual(own.count("\n"), body.count("\n"))
        self.assertEqual(own.strip(), "Chromium changes:")

    def test_a_trailer_of_the_commit_below_the_quote_stays_read(self):
        """The block ends at the first unindented line that is no header."""
        body = (self._chromium("Remove a flag.", "", "Co-Authored-By: Gemini <noreply@google.com>")
                + "\nCo-Authored-By: Claude Opus 5 <noreply@anthropic.com>")
        fields = (*HUMAN, *HUMAN, "[cr147] A flag is gone", body)
        self.assertEqual(detect_ai_tools_in_fields(*fields), ["Claude"])
        self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])

    def test_a_git_log_block_of_a_squash_merge_stays_read(self):
        """`git merge --squash` writes the same form for a change that the commit records."""
        body = ("Squashed commit of the following:\n\ncommit 57a7dfb4e2645b9c62d3a005436c815f4314b5e6\n"
                "Author: Dev <dev@example.com>\nDate:   Tue Apr 7 01:29:42 2026 -0700\n\n"
                "    Add the flag\n\n    Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>\n")
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "Merge the flag", body), ["Claude"])

    def test_a_sentence_that_ends_in_the_words_is_no_such_line(self):
        """electron/electron 3da8468c480f names the changes in prose, and no quote follows."""
        body = ("This adapts the related Chromium changes:\n\n"
                "https://chromium-review.googlesource.com/c/chromium/src/+/8163651\n"
                "Co-Authored-By: GitHub Copilot (GPT-5.3-Codex) <175728472+Copilot@users.noreply.github.com>\n")
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "feat: heap profiling", body), ["Copilot"])
        block = ("This adapts the related Chromium changes:\n\ncommit 57a7dfb\nAuthor: A <a@b>\n"
                 "Date:   Tue\n\n    Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>\n")
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "feat: heap profiling", block), ["Claude"])


class TestAVersionBumpOfHkubeQuotesThePreviousMessage(unittest.TestCase):
    """The version bumps of kube-HPC/hkube take the whole message of the commit before them and
    append ` .... bump version [skip ci]` (scripts/createVersion.sh at 4a57bc616f61). A credit in
    such a message belongs to the commit before, which stays credited: GitHub Action's
    17cc2d34134a quotes the co-author line of a squash merge, and c57a79361d49 a message without a
    body. The squash merge fb89350f0172 credits Copilot. The messages are the ones in the commit CSV
    and on GitHub, shortened."""

    ACTION = ("GitHub Action", "action@github.com")
    BUMP = ("Update job query parameters to use 'tags' array instead of single 'tag' string (#2414)",
            "Co-authored-by: Copilot <copilot@github.com> .... bump version [skip ci]")

    def test_a_bump_credits_no_tool(self):
        fields = (*self.ACTION, *self.ACTION, *self.BUMP)
        self.assertEqual(detect_ai_tools_in_fields(*fields), [])
        self.assertEqual(_mod.attributions_in_fields(*fields), "")
        self.assertEqual(_mod.unmatched_attributions(*self.ACTION, *self.ACTION, self.BUMP[1]), [])
        self.assertEqual(_mod.scope_texts(*self.BUMP), ("", ""))

    def test_a_bump_of_a_message_without_a_body_reads_no_subject(self):
        subject = ("Add conflict retry logic for etcd job status updates and corresponding tests "
                   "(#2505) .... bump version [skip ci]")
        self.assertEqual(_mod.scope_texts(subject, ""), ("", ""))

    def test_the_squash_merge_that_a_bump_quotes_credits_copilot(self):
        body = ("* Add health monitoring schema and Prometheus querier for service health checks\n\n"
                "Co-authored-by: Copilot <copilot@github.com>\n\n---------\n\n"
                "Co-authored-by: Copilot <copilot@github.com>")
        self.assertEqual(_mod.attributions_in_fields(
            *HUMAN, "GitHub", "noreply@github.com", "Add health monitoring  (#2424)", body),
            "Copilot:standard")

    def test_the_texts_by_line_are_the_texts_of_a_bump(self):
        texts = _mod._texts_by_line(*self.BUMP)
        self.assertEqual((texts["trailer"][0], texts["full_body"][0]), _mod.scope_texts(*self.BUMP))


class TestATrailerAfterAnEscapedLineBreakInABodyLine(unittest.TestCase):
    """A tool that writes the two characters `\\n` in place of a line break leaves its trailers
    in one line of the body, and the trailer scope reads them as lines of their own: tikv/pd
    34c56d780657 credits Claude Code, mkrueger/icy_tools dc45955601d9 Copilot CLI and elizaOS/eliza
    e908878f198c lists a commit that credits Codex. A list item reads its escapes too, as xtaci/smux
    148c01bcb4ad and SonicJs-Org/sonicjs 6df3b91cc86b have the trailers of their squash merges in
    one. A list item that names another commit by its hash keeps its escapes, because
    meziantou/Meziantou.Framework 0700bc2ff449 lists the messages of other commits in its release
    commit. The messages come from the commit logs and the commit CSV, shortened."""

    PD = ("schedule: reject unhealthy stores in scheduling and operator checks (#11146)",
          "ref tikv/pd#11143\\n\\nvalidateStore only invalidated an in-flight operator step once the\n"
          "target store hit the Down threshold (30min, configurable), leaving a\n"
          "long window where an operator kept running against a target that had\n"
          "them regardless of the target's reachability.\\n\\nSigned-off-by: person-29 "
          "<person1@example.com>\\n\\nCo-authored-by: Claude Sonnet 5 <noreply@anthropic.com>")
    ICY_TOOLS = ("Keep Tab within Icy Draw's font editor",
                 "Consume Tab after switching between the glyph and character areas so egui does "
                 "not continue global widget traversal.\\n\\nCo-authored-by: Copilot "
                 "<223556219+Copilot@users.noreply.github.com>")
    ELIZA = ("fix(plugin-elizacloud): retry total voice catalog outages (#23406)",
             "* fix(plugin-elizacloud): retry total voice catalog outages\n\n"
             "Validate canonical shared-tier upload payloads, bind their bytes to idempotency "
             "claims, and deliver request-scoped media into AgentRuntime.\\n\\nFixes #23385\\n\\n"
             "Co-authored-by: OpenAI Codex <noreply@openai.com>")
    RELEASE = ("Bump package versions (#1546)",
               "## Meziantou.Framework.Win32\n"
               "- 856a78797ba832a86f8a46d01a0a01b9cd9c3f8a: Use CsWin32 for RestartManager interop "
               "(#1497) Replace hand-authored Restart Manager native declarations with "
               "Microsoft.Windows.CsWin32 generated APIs and types.\\n\\nCo-authored-by: Copilot "
               "<223556219+Copilot@users.noreply.github.com>")
    SMUX = ("Harden short-write semantics in sendLoop",
            "- treat partial socket writes without explicit errors as io.ErrShortWrite\\n- add "
            "fault-injection tests for Write and WriteBuffers short-write paths\\n- verify original "
            "WriteBuffers errors are preserved\\n\\nCo-authored-by: Copilot "
            "<223556219+Copilot@users.noreply.github.com>")
    SONICJS = ("fix: restore type-check pass",
               "- update tsconfig, globals, and telemetry types so @sonicjs-cms/core compiles inside "
               "the workspace\\n- document failure analysis in docs/issues/type-check-failures.md "
               "and link to #330\\n\\nFixes #330\\n\\nGenerated with Claude Code\\nCo-Authored-By: "
               "Claude <noreply@anthropic.com>")

    def test_the_trailers_after_the_escapes_credit_their_tools(self):
        cases = ((("person-65", "person1@example.com"), self.PD, "Claude:standard"),
                 (("Tom Bloggs", "person204@example.org"), self.ICY_TOOLS, "Copilot:standard"),
                 (HUMAN, self.ELIZA, "Codex:standard"),
                 (("person-68", "person292@example.org"), self.SMUX, "Copilot:standard"),
                 (HUMAN, self.SONICJS, "Claude:standard;Claude:convention"))
        for author, (subject, body), attributions in cases:
            with self.subTest(subject=subject):
                self.assertEqual(_mod.attributions_in_fields(
                    *author, "GitHub", "noreply@github.com", subject, body), attributions)

    def test_the_signed_off_line_after_an_escape_is_a_trailer(self):
        self.assertEqual(_extract_trailers(self.PD[1]),
                         "Signed-off-by: person-29 <person1@example.com>\n"
                         "Co-authored-by: Claude Sonnet 5 <noreply@anthropic.com>")

    def test_a_list_item_that_names_another_commit_keeps_its_escapes(self):
        fields = ("github-actions[bot]", "41898282+github-actions[bot]@users.noreply.github.com",
                  "GitHub", "noreply@github.com", *self.RELEASE)
        self.assertEqual(detect_ai_tools_in_fields(*fields), [])
        self.assertEqual(_extract_trailers(self.RELEASE[1]), "")

    def test_a_list_item_without_a_hash_reads_its_escapes(self):
        for marker in ("-", "*", "+", "1.", "2)"):
            with self.subTest(marker=marker):
                body = f"{marker} first\\n{marker} second\\n\\nCo-authored-by: Claude <noreply@anthropic.com>"
                self.assertEqual(_extract_trailers(body), "Co-authored-by: Claude <noreply@anthropic.com>")
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "chore: update", body), ["Claude"])

    def test_a_word_of_hexadecimal_letters_is_no_hash(self):
        """The hash of a listed commit has at least seven characters, as git abbreviates it, and a
        list item that begins with a shorter word reads its escapes."""
        body = "- add: first\\n\\nCo-authored-by: Claude <noreply@anthropic.com>"
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "chore: update", body), ["Claude"])

    def test_the_texts_by_line_are_the_texts_the_heuristics_read(self):
        for subject, body in (self.PD, self.ICY_TOOLS, self.ELIZA, self.RELEASE, self.SMUX, self.SONICJS):
            with self.subTest(subject=subject):
                texts = _mod._texts_by_line(subject, body)
                self.assertEqual((texts["trailer"][0], texts["full_body"][0]),
                                 _mod.scope_texts(subject, body))


