class TestTheCreditsOfClaudeThatTheReviewOf1105Corrected(unittest.TestCase):
    """Commits that the rows credited to Claude for a line that records no change of Claude's in
    the commit, or that names the model that another agent ran: the walkthrough of a pull request,
    a quoted footer, a section of the description, the reason for deleting tests, a thread id of
    Codex under Claude's session token, and a Claude model that omp, Theia's AI or Lodekeeper ran.
    The messages come from GitHub's API, shortened."""

    def test_a_line_that_records_no_change_of_claude_s_credits_no_claude(self):
        cases = (
            # NomicFoundation/slang 43c60c273958
            ("feat(abi): Serialize storage layouts as JSON (#2262)",
             "[Code\nwalkthrough](https://claude.ai/artifact/3SaVSwN9SXGryLNsDVRh1n?sk=Jo7KH6QjzRBQb2ryxns3hA)\n"
             "generated by Claude, for convenience."),
            # marin-community/marin d1fef7a20923
            ("[agents] Suppress self-credit attribution and hoist PR-body rules (#6780)",
             "PR #6778 shipped a `Problem`/`Fix`/`Verification` body with a\n"
             "\"Generated with Claude Code\" footer — against every PR rule we have —\n"
             "because of\ntwo gaps."),
            # rerun-io/rerun aa985448af28
            ("ci: BuildKite PR cutover",
             "<sub>The \"Behaviour changes\" section was written by Claude (an\nLLM).</sub>"),
            # devbisme/skidl 0c1273b98450
            ("Moved Sexp schematic generation tests to ai_tests subdirectory since they were written by "
             "Claude.", ""),
        )
        for subject, body in cases:
            with self.subTest(subject=subject):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, subject, body), [])

    def test_a_codex_thread_id_under_claude_s_session_token_credits_codex_alone(self):
        """GaijinEntertainment/daScript f52c216ff71e, and the session link of 0xPlaygrounds/rig
        5bfe20bdd055, which stays Claude Code's."""
        fields = (*HUMAN, *HUMAN, "Keep cache runner probes inside their private directories.",
                  "Co-Authored-By: OpenAI Codex <noreply@openai.com>\n"
                  "Claude-Session: 01a16b41-2edd-7200-a890-9a77d24de8d4")
        self.assertEqual(detect_ai_tools_in_fields(*fields), ["Codex"])
        self.assertEqual(_mod.attributions_in_fields(*fields), "Codex:standard")
        self.assertEqual(_mod.attributions_in_fields(
            *HUMAN, *HUMAN, "docs: add Archestra to \"Who is using Rig?\" section (#1925)",
            "Claude-Session: https://claude.ai/code/session_01HsQBW8AXM5CBMDBGEBd5jk"), "Claude:standard")

    def test_a_claude_model_that_another_agent_ran_credits_that_agent(self):
        cases = (
            # TecharoHQ/anubis 3a6f57333d28
            (("Jane", "141632421+person12@users.noreply.github.com"),
             "fix(localization): correct Dutch go_home typo (#1892)",
             "Assisted-by: Claude Opus 4 via omp\nCo-authored-by: Tom Bloggs <person197@example.org>", "oh-my-pi:convention"),
            # systemd/systemd 9ed12a81b251
            (("Mark Poe", "first97.last@example.org"),
             "resolved: Add ifindex=0 support for BrowseServices to browse all mDNS interfaces",
             "Assisted-by: Claude Opus 4.6 (Eclipse Theia IDE AI)", "Theia AI:convention"),
            # ChainSafe/lodestar b87b37f4d02b and c4af2af04058, which Lodekeeper authored
            (("Lodekeeper", "258435968+lodekeeper@users.noreply.github.com"),
             "fix: await processFn to prevent buffer pool race condition (#8877)",
             "**AI Disclosure:** This PR was authored with AI assistance\n(Lodekeeper/Claude).\n\n"
             "Co-authored-by: lodekeeper <lodekeeper@users.noreply.github.com>",
             "OpenClaw:account;OpenClaw:standard;OpenClaw:convention"),
            (("Lodekeeper", "258435968+lodekeeper@users.noreply.github.com"),
             "chore: cleanup bigint buffer utils (#8863)",
             "*Generated with AI assistance (Claude/OpenClaw). Human-supervised and\ntested.*\n\n"
             "Co-authored-by: lodekeeper <lodekeeper@users.noreply.github.com>",
             "OpenClaw:account;OpenClaw:standard;OpenClaw:convention"),
        )
        for author, subject, body, others in cases:
            with self.subTest(subject=subject):
                fields = (*author, "GitHub", "noreply@github.com", subject, body)
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), others)


