class _TheCommitsOfARow:
    """The check that the classes below share: each commit, keyed by its link, is in the evidence
    of its row, the row reads it, and the commit credits what its entry names."""

    COMMITS: dict = {}

    def test_each_commit_is_read_by_its_row_and_credits_its_tool(self):
        evidence = {r["id"]: r["evidence"].split() for r in AI_COMMIT_PATTERNS}
        for url, (identities, row, subject, body, tools, attributions) in self.COMMITS.items():
            with self.subTest(url=url, row=row):
                self.assertIn(url, evidence[row])
                fields = (*identities, subject, body)
                self.assertIn(row, _mod.matched_rules_in_fields(*fields))
                self.assertEqual(detect_ai_tools_in_fields(*fields), tools)
                self.assertEqual(_mod.attributions_in_fields(*fields), attributions)
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])


