    def test_lines_that_name_no_change_of_the_tool_are_not_read(self):
        """A person who writes about Codex, a title that continues after the placeholder's words,
        a merge by hand, Inline alone of the tracker, the name of streamlit's workflow file, and
        the marker of another engine."""
        rows = {"codex-full-body-14", "codex-full-body-15", "codex-full-body-16", "codex-full-body-17",
                "copilot-full-body-14", "copilot-full-body-15", "copilot-full-body-16",
                "copilot-full-body-17", "cursor-full-body-11", "cursor-full-body-12"}
        for body in ("Written by Jane Doe on Codex day",
                     "the tests were written by gpt-5 in codex style",
                     "Add a Codex-generated pull request template",
                     "merged by hand. Its package changes are identical to the original",
                     "Merged by Copilot CLI maintainers",
                     "Impacted by AI (Inline)",
                     "- Weekly GitHub Actions workflow (`ai-fix-flaky-e2e-tests.yml`) that",
                     "<!-- gh-aw-agentic-workflow: Guidelines Bot, engine: claude, model: claude-opus-4-8 -->"):
            with self.subTest(body=body):
                ids = _mod.matched_rules_in_fields(*HUMAN, *WEB, "fix: x", "Summary\n\n" + body)
                self.assertFalse(rows & set(ids))

