# The six tools, each with the name that its rows read in the forms that `_with_each_tool` repeats.
# The rows of Gemini read `Gemini CLI` in these forms and not a bare `Gemini`.
_SIX_TOOLS = (("Claude", "Claude"), ("Codex", "Codex"), ("Copilot", "GitHub Copilot"),
              ("Cursor", "Cursor"), ("Gemini", "Gemini CLI"), ("OpenCode", "OpenCode"))


def _with_each_tool(lines: tuple, credited: bool = True, leave_out: tuple = ()) -> tuple:
    """Each line once with the name of each of the six tools in place of `{tool}`, with that tool,
    or with no tool where `credited` is false, so that the rows of every tool that share a form
    are tested on it."""
    return tuple((((tool,) if credited else ()), line.format(tool=name))
                 for tool, name in _SIX_TOOLS if tool not in leave_out for line in lines)


