def _review_fields(author: tuple, committer: tuple, subject: str, body: str) -> tuple:
    """The fields of a commit of the review of 2026-11-05."""
    return (*author, *committer, subject, body)


class _TheCommitsOfTheReviewOf1105:
    """The checks of the commits that a class of the review of 2026-11-05 lists in COMMITS: each
    commit, a real one shortened to the lines that the rows read, is read by exactly the rows
    that it names, with the attributions that it names, and each row links the commit in its
    evidence."""

    COMMITS: dict = {}

    def test_each_commit_is_read_by_its_rows(self):
        evidence = {r["id"]: r["evidence"].split()
                    for r in (*AI_COMMIT_PATTERNS, *_mod.OTHER_AI_COMMIT_PATTERNS)}
        for url, (author, committer, subject, body, rows, six, other) in self.COMMITS.items():
            with self.subTest(url=url):
                fields = _review_fields(author, committer, subject, body)
                matched = [*_mod.matched_rules_in_fields(*fields),
                           *_mod.matched_other_rules_in_fields(*fields)]
                self.assertEqual(sorted(matched), sorted(rows))
                self.assertTrue(any(url in evidence[row] for row in rows))
                self.assertEqual(_mod.attributions_in_fields(*fields), six)
                self.assertEqual(_mod.other_attributions_in_fields(*fields), other)


