    def test_the_login_of_jules_s_app_that_another_app_now_has_is_not_jules(self):
        """GitHub gave the login labs-code-app[bot] of Jules's bot user 161369871 to another app,
        bot user 335182600, and the Jules rows read the login only with Jules's id."""
        for line in ("labs-code-app[bot] <335182600+labs-code-app[bot]@users.noreply.github.com>",):
            name, _, email = line.partition(" <")
            fields = (name, email.rstrip(">"), *GITHUB, "chore: update", "")
            self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])
            self.assertEqual(_mod.detect_other_ai_tools_in_fields(
                *HUMAN, *GITHUB, "chore: update", "Co-authored-by: " + line), [])
        self.assertEqual(_mod.detect_other_ai_tools_in_fields(
            "labs-code-app[bot]", "161369871+labs-code-app[bot]@users.noreply.github.com", *GITHUB,
            "chore: update", ""), ["Jules"])
        self.assertEqual(_mod.detect_other_ai_tools_in_fields(
            "junie-eap[bot]", "199612962+junie-eap[bot]@users.noreply.github.com", *GITHUB,
            "chore: update", ""), ["Junie"])

    def test_the_label_tool_not_named_gives_way_to_lovable(self):
        """tool-not-named-trailer-02 reads the login gpt-engineer-app[bot] as a GPT model, and a
        commit that names Lovable is Lovable's."""
        url = "https://github.com/gptme/gptme/commit/e47a7e1520839e5888290b1d64c2508c5060ec71"
        author, committer, subject, body = self.COMMITS[url][:4]
        fields = _review_fields(author, committer, subject, body)
        self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), ["Lovable"])


