        """The Claude identities of neomjs/neo, such as Clio, the author of 93a4f3189882, and the
        project's owner person-64 are left to other rows."""
        for author, body in ((("Clio", "neo-fable-clio@neomjs.com"), ""),
                             (("Neo Claude Opus", "neo-opus-4-7@neomjs.com"), ""),
                             (HUMAN, "Co-authored-by: person-64 <person269@example.com>")):
            with self.subTest(author=author, body=body):
                tools = detect_ai_tools_in_fields(*author, *GITHUB, "chore: update", body)
                self.assertNotIn("Gemini", tools)
                self.assertNotIn("Codex", tools)
                self.assertEqual(
                    _mod.detect_other_ai_tools_in_fields(*author, *GITHUB, "chore: update", body), [])


