    def test_each_commit_credits_its_tool_as_its_lines_record_and_none_of_the_six(self):
        evidence = {r["id"]: r["evidence"].split() for r in _mod.OTHER_AI_COMMIT_PATTERNS}
        for url, (identities, subject, body, rows, attributions) in self.COMMITS.items():
            with self.subTest(url=url):
                self.assertTrue(any(url in evidence[row] for row in rows))
                fields = (*identities, subject, body)
                self.assertEqual(set(_mod.matched_other_rules_in_fields(*fields)), rows)
                self.assertEqual(_mod.other_attributions_in_fields(*fields), attributions)
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])

