class TestTheSubjectPrefixOfCodex(unittest.TestCase):
    """OpenAI's skill wrote `[codex] {description}` into the title of a pull request, and the
    maintainer decided that the prefix credits Codex in lowercase only."""

    def test_the_lowercase_prefix_of_a_subject_credits_codex(self):
        for subject, body in (("[codex] Fix OSC 8 hyperlink state transitions (#1112)", ""),
                              ("[codex] Simplify infrastructure", ""),
                              ("Merge pull request #12 from a/b", "[codex] Add foo"),
                              ("Squash of three commits", "* [codex] Add foo")):
            with self.subTest(subject=subject, body=body):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, subject, body), ["Codex"])

    def test_a_dash_list_item_credits_nothing(self):
        """GitHub writes a squashed commit as a `* ` line. raycast/extensions 2c65c45fdbe7 and
        bad036d13797 list subjects of other commits after a `- `, and their changes are in other
        extensions or another repository."""
        for subject, body in (("Update search-router extension (#31832)",
                               "- Pull contributions\n- [codex] Fix Spotify player lyrics command (#29198)"),
                              ("Add uploadkit extension (#29111)",
                               "- [codex] Delete project files from R2 (#28)"),
                              ("Squash of three commits", "- [codex] Add foo")):
            with self.subTest(body=body):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, subject, body), [])

    def test_another_spelling_or_place_of_the_prefix_credits_nothing(self):
        for subject in ("[Codex] Opt Mistral", "[CODEX] Opt Mistral", "[Platform][codex] Align",
                        "[codex](https://x) y", "fix [codex] thing", 'Revert "[codex] Add foo"',
                        "[codex]", "[app-server] Add foo"):
            with self.subTest(subject=subject):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, subject, ""), [])


class TestTheFooterOfKoan(unittest.TestCase):
    """Kōan writes `_Generated by [Kōan](https://koan.anantys.com)_` into the description of its
    pull requests and at the end of the quality report that it adds there (build_koan_footer() in
    koan/app/pr_footer.py of Anantys-oss/koan), and a squash merge copies the description. The
    footer credits Koan as `standard`, and a line above it that names a Claude model and Kōan
    stays Claude's, so that such a commit is in both commit CSVs."""

    # The commits that the evidence of koan-full-body-01 links, shortened to the line of Claude,
    # the quality report and the footer
    EVIDENCE = {
        "https://github.com/aio-libs/aiohttp/commit/d60a88e283e0dbc7d91d831b43e3f456d8d1a39f": (
            "Adopt PEP 639 SPDX license metadata (#13891)",
            "Drafted with Claude Opus 5 via koan; reviewed by @person.\n\n---\n### Quality Report\n\n"
            "**Code scan**: clean\n\n**Branch hygiene**: clean\n\n"
            "_Generated by [Kōan](https://koan.anantys.com)_"),
        "https://github.com/aio-libs/aiohttp/commit/1f2aadd234182ba9dd39fd54028d48772361b9f8": (
            "Drop leftover pip --user settings from CI workflow (#13721)",
            "Drafted with Claude Opus 5 (Kōan); reviewed by: pending operator review.\n\n---\n"
            "### Quality Report\n\n**Code scan**: clean\n\n**Tests**: failed (FAILED)\n\n"
            "_Generated by [Kōan](https://koan.anantys.com)_"),
        "https://github.com/aio-libs/multidict/commit/7194baa3206cdbf4d1ca7d3bc76e8474114d588f": (
            "Move project metadata from setup.cfg to pyproject.toml (#1646)",
            "Drafted with Claude Opus 5 via Kōan; pending review by the operator.\n\n---\n"
            "### Quality Report\n\n**Code scan**: clean\n\n**Tests**: failed (FAILED)\n\n"
            "_Generated by [Kōan](https://koan.anantys.com)_"),
    }

    # (the tools of both heuristics files that a body credits, exactly, the body)
    READ = (
        (("Koan",), "_Generated by [Kōan](https://koan.anantys.com)_"),
        # build_pr_footer() adds the provider, the model, the head commit and the duration.
        (("Koan",), "Fixes the parser.\n\n---\n_Generated by [Kōan](https://koan.anantys.com)_ "
                    "_(Claude · model opus-4-6 · HEAD=abc1234 · 5m02s)_"),
        (("Koan",), "_GENERATED BY [KŌAN](https://koan.anantys.com)_"),
        # aio-libs/yarl b3adeb98f538 names Kōan beside Claude without the footer.
        (("Claude",), "Drafted with Claude Opus 5 via Koan; reviewed by @person."),
        # The footer of a review comment and of the comment that links a new pull request, which
        # records no change, and a link to Kōan's page
        ((), "_Automated review by [Kōan](https://koan.anantys.com)_ _(Claude · model opus-4-6)_"),
        ((), "_Automated by [Kōan](https://koan.anantys.com)_"),
        ((), "See https://koan.anantys.com for the agent."),
    )

    @staticmethod
    def _fields(subject: str, body: str) -> tuple:
        return (*HUMAN, "GitHub", "noreply@github.com", subject, body)

    def test_every_commit_of_the_evidence_credits_koan_and_claude(self):
        evidence = next(r["evidence"] for r in _mod.OTHER_AI_COMMIT_PATTERNS
                        if r["id"] == "koan-full-body-01")
        self.assertEqual([url for url in evidence.split() if "/commit/" in url], list(self.EVIDENCE))
        for url, (subject, body) in self.EVIDENCE.items():
            with self.subTest(url=url):
                fields = self._fields(subject, body)
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), ["koan-full-body-01"])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "Koan:standard")
                self.assertEqual(_mod.matched_rules_in_fields(*fields), ["claude-full-body-05"])
                self.assertEqual(_mod.attributions_in_fields(*fields), "Claude:convention")

    def test_each_body_credits_exactly_its_tools(self):
        for tools, body in self.READ:
            with self.subTest(body=body):
                fields = self._fields("fix: a thing", body)
                self.assertEqual({*detect_ai_tools_in_fields(*fields),
                                  *_mod.detect_other_ai_tools_in_fields(*fields)}, set(tools))


class TestTheCoauthorLineOfKoan(unittest.TestCase):
    """GitHub writes a co-author line for the author of the commits of a pull request in its
    squash merge. Kōan's commits land under the git identity of its operator, and
    setup_git_identity() in koan/app/startup_manager.py of Anantys-oss/koan names their author
    Kōan when KOAN_EMAIL is set. The line credits Koan as `convention`, because it stands at a
    person's address."""

    # The squash merges that the evidence of koan-trailer-01 links, with fictional addresses: (the
    # subject, the body, the tools of the six that the commit credits)
    EVIDENCE = {
        "https://github.com/esphome/aioesphomeapi/commit/828c30aa1a24a1161676cce4a5842053868b0292": (
            "Add explicit __all__ to model to stop leaking stdlib imports (#1749)",
            "Co-authored-by: Koan <person300@example.org>", []),
        "https://github.com/esphome/aioesphomeapi/commit/8a520b82ff4edd1985ade242f0cd15998632f958": (
            "Add benchmarks for callback dispatch with/without exception guards (#1757)",
            "Co-authored-by: Koan <person300@example.org>", []),
        "https://github.com/esphome/aioesphomeapi/commit/7647f3f3d86ee7e11746d49bd1e26fe02cf6cef7": (
            "Isolate user-callback exceptions in process_packet (#1762)",
            "Co-authored-by: Koan <person300@example.org>", []),
        "https://github.com/Bluetooth-Devices/bleak-esphome/commit/355cac657837281220eab7e0701b64713e945054": (
            "docs: explain Bluetooth Proxy architecture and library scope (#294)",
            "Co-authored-by: Claude Opus 4.7 (1M context) <noreply@anthropic.com>\n"
            "Co-authored-by: Kōan <person301@example.org>\n"
            "Co-authored-by: pre-commit-ci[bot] <66853113+pre-commit-ci[bot]@users.noreply.github.com>",
            ["Claude"]),
    }

    def test_every_commit_of_the_evidence_credits_koan_as_a_convention(self):
        evidence = next(r["evidence"] for r in _mod.OTHER_AI_COMMIT_PATTERNS
                        if r["id"] == "koan-trailer-01")
        self.assertEqual([url for url in evidence.split() if "/commit/" in url], list(self.EVIDENCE))
        for url, (subject, body, tools) in self.EVIDENCE.items():
            with self.subTest(url=url):
                fields = (*HUMAN, "GitHub", "noreply@github.com", subject, body)
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), ["koan-trailer-01"])
                self.assertEqual(_mod.other_attributions_in_fields(*fields), "Koan:convention")
                self.assertEqual(detect_ai_tools_in_fields(*fields), tools)

    def test_koan_with_a_surname_a_longer_name_and_another_token_are_not_read(self):
        for body in ("Co-authored-by: Koan Doe <person302@example.org>",
                     "Co-authored-by: Koanfan <person303@example.org>",
                     "Reviewed-by: Koan <person300@example.org>"):
            with self.subTest(body=body):
                fields = (*HUMAN, "GitHub", "noreply@github.com", "fix: a thing", body)
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])


