    def test_melvinbot_s_line_outside_a_suggestion_credits_nothing(self):
        """The co-author line at MelvinBot's noreply address is the line of the person who requested
        the change, which the account's workflow writes into its own commits, and it is not the
        account's standard line. The account's noreply address as the author credits nothing,
        because the account merged version bumps under it."""
        for author, subject, body in (
                (HUMAN, "Docs: Workspace Admins can delete a member's Draft report", self.LINE),
                (HUMAN, "Update Personal Karma help article to match new toggle UI",
                 "- Update toggle label reference\n\n" + self.LINE),
                (("MelvinBot", "MelvinBot@users.noreply.github.com"),
                 "Merge pull request #212 from Expensify/botify-bump-version-57167f04", "")):
            with self.subTest(subject=subject):
                fields = (*author, *GITHUB, subject, body)
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
                self.assertEqual(_mod.attributions_in_fields(*fields), "")

    def test_melvinbot_s_own_commit_with_its_line_credits_claude_as_its_account(self):
        """0005439fd321 of Expensify/App, which MelvinBot made at its own request."""
        fields = ("MelvinBot (via MelvinBot)", "infra+melvinbot@expensify.com",
                  "MelvinBot (via MelvinBot)", "infra+melvinbot@expensify.com",
                  "Update Personal Karma help article to match new toggle UI",
                  "- Update toggle label reference\n\n" + self.LINE)
        self.assertEqual(_mod.matched_rules_in_fields(*fields), ["claude-author-16"])
        self.assertEqual(_mod.attributions_in_fields(*fields), "Claude:account")

    def test_a_credit_of_roo_code_that_names_no_identity_of_roomote_stays_a_convention(self):
        fields = (*HUMAN, *HUMAN, "chore: update", "Assisted-by: Roo Code (Google Gemini)")
        self.assertEqual(_mod.other_attributions_in_fields(*fields), "Roo Code:convention")

    def test_the_model_that_planned_the_change_credits_nothing(self):
        for line in ("Plan-Model: claude-opus-4.8", "Plan-Model: gpt-5.3-codex",
                     "Plan-Model: grok-4.7", "Plan-Model: gemini-3.1-pro"):
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "feat: x", line + "\nMade-with: Jane Doe")
                self.assertEqual(detect_ai_tools_in_fields(*fields), [])
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [])

    def test_a_model_that_implemented_the_change_credits_no_tool_of_the_six(self):
        fields = (*HUMAN, *HUMAN, "feat: x", "Impl-Model: gpt-5.3-codex")
        self.assertEqual(detect_ai_tools_in_fields(*fields), [])
        self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), [_mod.UNNAMED_TOOL])



