    def test_lines_beside_them_credit_none_of_the_six(self):
        """The lines beside the credits that name no tool of the six, or name it in a form that
        credits no change."""
        for body in (
                "MF,CC", "Co-authored-by: MF <noreply@anthropic.com>",
                "Co-authored-by: CC <cc@example.com>", "Co-authored-by: AB,CC",
                "Reviewed-by: [CC] <noreply@anthropic.com>",
                "Assisted-by: <cursor-user@example.com>", "Assisted-by: <Cursor> for code review",
                "Assisted-by: ChatGPT and Copilot Fallback",
                "Generated-by : scripts/gen.sh (cursor position fix)",
                "Co-Authored-By : Claude <noreply@anthropic.com>",
                "agent-tool: <copilot-cli|copilot-chat|claude-cli|cursor|other|n/a>",
                "agent-tool: <cursor|copilot-chat>",
                "X-AI-Tool: Kiro", "X-AI-Tool: Human", "XX-AI-Tool: Claude",
                "AI: Ignore codex file", "AI: GPT 5.2 Codex", "AI: Codex review",
                "Agent: codex-1",
                "Client: Grok CLI via cmux", "Client / agent tooling: Cursor",
                "Client / agent tooling: Codex Desktop multi-agent review",
                "Client / agent tooling: <client>",
                "Agent session: `019faa88-564d-7830-b349-c29e1f710803`",
                "If the script prints `codex <id>`, use ``Agent session: `codex resume <id>` ``.",
                "- Agent: codex-1", "- Tool: codex-rs", "> - Harness: Codex desktop",
                "  - Tool: GitHub Copilot Business, Claude Sonnet 4.6, agent mode",
                "Agent: github-copilot/gpt-6-luna/01a1b796-3554-706f-b584-0c93a34052d9",
                "Agent: Autonomous fix from user request", "Agent: Claude Stiles",
                "Agent: Claude Opus 4.8 (Kiro)",
                "- **Tool:** <!-- Amp, Cursor, Copilot, Claude Code, Codex, etc. -->",
                "- **Model:** Claude Sonnet 4.6",
                "Agent-Model: claude-opus-5-5", "Coding-Harness: claude-code-router",
                "AI (Codex) was used to write the commit message.",
                "AI (Codex 5.6) was used to review the code.",
                "AI-attribution: AIA Eh Cursor v1.0", "AIA Eh v1.0 Cursor",
                "AI-attribution: AIA PAI Ce Hin R claude-4.6-opus via Cursor v1.0",
                "AI-attribution: AIA PAI Ce Hin R Claude Code (Cursor) v1.0",
                "AI-attribution: AIA PAI Ce Hin R codex-mini v1.0"):
            with self.subTest(body=body):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "chore: update", body), [])
        for subject in ("agent: codex/sandbox fix",
                        "tool: give Claude skill on repo policy checking (#26636)",
                        "agent: Copilot (#123)", "Client: change cursor using node action information "
                        "of pathfinder", "harness: add codex and qwen-code CLI harnesses"):
            with self.subTest(subject=subject):
                self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, subject, ""), [])

    def test_a_spaced_generated_by_line_is_read_for_each_tool(self):
        """The six rows of a mistyped or spaced key read `Generated-by` with a space before the
        colon for the tool that each reads, as `Generated-by : Cursor/Claude` of
        kubernetes-sigs/kubebuilder 249064d3be5d credits Cursor. Gemini alone names no product."""
        for line, row, tools in (("Generated-by : Claude Code", "claude-full-body-53", ["Claude"]),
                                 ("Generated-by : Codex", "codex-full-body-43", ["Codex"]),
                                 ("Generated-by : GitHub Copilot", "copilot-full-body-40", ["Copilot"]),
                                 ("Generated-by : Cursor", "cursor-full-body-34", ["Cursor"]),
                                 ("Generated-by : Gemini CLI", "gemini-full-body-31", ["Gemini"]),
                                 ("Generated-by : OpenCode", "opencode-full-body-33", ["OpenCode"])):
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "chore: update", line)
                self.assertIn(row, _mod.matched_rules_in_fields(*fields))
                self.assertEqual(detect_ai_tools_in_fields(*fields), tools)
        self.assertEqual(detect_ai_tools_in_fields(*HUMAN, *HUMAN, "chore: update",
                                                   "Generated-by : Gemini"), [])

    def test_a_squash_merge_of_a_seat_under_both_adapters_credits_both(self):
        """Team-Commonly/commonly c16d4c9845ef: Commonly's hook adds the line of each adapter, and
        a seat under the adapter claude that rewrote the commits adds its line below the line of
        the seat under the adapter codex."""
        fields = (*HUMAN, *GITHUB, "test(auth): exercise new-account OAuth through first session (#2818)",
                  "Agent-Model: codex/gpt-6.1-sol/medium\nAgent-Model: claude/claude-haiku-5-5/default")
        self.assertEqual(detect_ai_tools_in_fields(*fields), ["Claude", "Codex"])


