    def test_lines_beside_them_credit_nothing(self):
        """The lines beside the credits that the rows leave unread."""
        for body in (
                "Plan-Model: claude-opus-5.5", "Suggested-Impl-Model: claude-opus-5.5",
                "Impl-Model: claude", "Impl-Model: Claude Code", "Impl-Model: claude-opus-5 via Cursor",
                "Impl-Model: Claude Stiles", "Impl-Model: Codex", "Impl-Model: Codex 5.3 via Cursor",
                "Impl-Model: grok 4.5 and Opus 5", "Impl-Model: grok-4.5, Cursor",
                "Impl-Model: opus", "Impl-Model: Opus Smith", "Plan-Model: auto",
                "Impl-Model: autonomous", "Impl-Model: automatic", "Assisted-by: auto",
                "Assisted-by: composer.json", "Assisted-by: Composer 2.5 Fastly",
                "Co-authored-by: haiku <haiku@example.com>", "Co-authored-by: Opus Magnum <ai@example.org>",
                "Co-authored-by: haiku <ai.bot@salesforce.com>",
                "Co-authored-by: Kimi K3 Code <noreply@moonshot.ai>", "AI-Assisted: no", "AI-Assisted: yes/no", "AI-Assisted: (yes/no) [tool]",
                "AI-Assisted: Yes. Implements responsive sidebar on desktop (>=768px)",
                "AI-Assisted: yes (Co-pilot for unit tests)",
                "AI-assisted: DeepSeek v4-pro, reviewed by OpenDAL regression team",
                "AI-assisted: GPT-5 helped write the commit message.", "AI-Assisted: yes (o3 for review)",
                "AI-Generated: false", "AI-Generated: tests written by hand", "AI-generated :(",
                "AI-Model: Gemini 3 Flash", "AI-Model: gpt-engineer-app",
                "AI-provider-model: xAI / grok-4.6", "Model: gpt-5", "Agent: ChatGPT Codex",
                "AI-Agent: ChatGPT, Gemini", "- AI-Agent: ChatGPT",
                "agent-model: unknown",
                "agent-tool: unknown-fallback", "- agent tools: unknown manage_constraint op now errors",
                "AI-Attribution: AIA,Entirely human-created,v1.0", "AI-Attribution: AIA No AI v1.0",
                "AI-attribution: AIA EAI Ce Nc Hin Nr v1.0",
                "AI-attribution: AIA PAI Ce Hin R gemini-2.5-pro v1.0",
                "AI-attribution: AIA PAI Ce Hin R Grok Build v1.0",
                "AIA: http://crt.example.com/ca.crt",
                "Example: `AI-attribution: AIA EAI Hin R claude-4-sonnet v1.0`",
                "Not developed with AI assistance.",
                "The description was drafted with AI assistance.",
                "AI disclosure: not written with AI assistance",
                "Note: this PR was not generated by an AI coding agent",
                "This PR was reviewed by an AI agent.",
                "This PR description was prepared by an AI agent.",
                "This commit was authored by an AI agent (breken-ai).",
                "The rule: this PR was generated by an AI coding agent",
                "AI-Assisted: no (Gemini)"):
            with self.subTest(body=body):
                fields = (*HUMAN, *HUMAN, "chore: update", body)
                found = _mod.detect_other_ai_tools_in_fields(*fields)
                self.assertNotIn(_mod.UNNAMED_TOOL, found)
                self.assertNotIn("Gemini (unspecified)", found)
        for subject in ("ai-model: gpt-4o-mini as default model",
                        "AI-assisted: GPT-5 support in the client"):
            with self.subTest(subject=subject):
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*HUMAN, *HUMAN, subject, ""), [])

    def test_a_named_tool_takes_the_commit(self):
        """A line that names a tool beside a line of the label makes the commit that tool's: the
        client of the provenance footer of elizaOS/eliza 2b861fa2bd6f, Cursor beside the model in
        the attribution statement of openshift-kni/numaresources-operator 95a64f6375a8, and Hermes
        Agent beside `AI-Assisted: yes` of JurajNyiri/HomeAssistant-Tapo-Control 5fdd5dbe7153."""
        cases = (
            ("AI-provider-model: OpenAI / gpt-5.6-sol\nClient: codex", ["Codex"], []),
            ("Assisted-by: Cursor v1.1.6\nAssisted-by-model: claude-4-sonnet\n"
             "AI-attribution: AIA EAI Hin R claude-4-sonnet v1.0", ["Cursor"], []),
            ("AI-Assisted: yes\nAI-Tool: Hermes Agent (DeepSeek V4.1 Flash)", [], ["Hermes Agent"]),
            ("AI-Assisted: yes (Claude Opus 4.7)", ["Claude"], []),
            ("AI-Assisted: yes (Gemini CLI)", ["Gemini"], []),
            ("Agent: ChatGPT\nModel: GPT-5.6 Sol\nCoding agent: Codex", ["Codex"], []),
        )
        for body, six, other in cases:
            with self.subTest(body=body):
                fields = (*HUMAN, *HUMAN, "fix: x", body)
                self.assertEqual(detect_ai_tools_in_fields(*fields), six)
                self.assertEqual(_mod.detect_other_ai_tools_in_fields(*fields), other)


