    def test_lines_beside_them_credit_nothing(self):
        """The forms of these keys that no row reads: a role of analysis after Tool-Assisted, the
        co-author of an original commit that the change does not contain, the harnesses of a
        council of Meta's Sentinel agent, which also name a run that only verified, a key of a
        single commit, a person after Co-author, a signature without a runtime, a model after the
        slash of an Agent line and the item Review. tool-not-named-full-body-07 reads a model alone
        after a mistyped key (TestTheKeysAndAgentsDecidedOn1109)."""
        for body in (
                "Tool-Assisted: Claude Code (claude-opus-4-8)\n"
                "  Role: root-cause analysis, cross-project bisection",
                "Original-Commit-Author: Ann Roe <ann@example.com>\n"
                "Original-Co-Author: Claude Fable 5 <noreply@anthropic.com>\n"
                "Replacement-Classification: redesigned replacement; original commit not cherry-picked",
                "Sentinel-Council-Run: council_1786482200_0bc2c44f\nSentinel-Harness: codex\n"
                "Sentinel-Harness: claude",
                "Assisted in Test: Gemini\nDocs-By: Claude Sonnet 4.5 <noreply@anthropic.com>",
                "AI-Assistant: GPT-5.2 via GitHub Copilot",
                "Co-author: Jules Roe <jules@example.com>",
                "Agent-Signature: unknown-model/unknown-reasoning on behalf of Ann Roe",
                "Agent: Codex/GPT-6",
                "- Review: Codex (GPT-6.1-sol).",
                "AssistedBy: cloude"):
            with self.subTest(body=body):
                fields = (*HUMAN, *HUMAN, "chore: update", body)
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), [])

    def test_the_keys_of_a_co_author_or_an_assistant_are_read_for_each_of_the_six(self):
        """The six rows of a mistyped or spaced key read the co-author line without -by,
        Co-author, Co-authored-with, AssistedBy and Co-Generated for the tool that each reads.
        Gemini alone names no product."""
        for line, row, tools in (("AssistedBy: Claude Code", "claude-full-body-53", ["Claude"]),
                                 ("Co-Authored: OpenAI Codex", "codex-full-body-43", ["Codex"]),
                                 ("Co-author: GitHub Copilot", "copilot-full-body-40", ["Copilot"]),
                                 ("Co-authored-with: Cursor", "cursor-full-body-34", ["Cursor"]),
                                 ("Co-Generated: Gemini CLI", "gemini-full-body-31", ["Gemini"]),
                                 ("Co-Authored: OpenCode", "opencode-full-body-33", ["OpenCode"]),
                                 ("Co-author: Gemini", None, [])):
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "chore: update", line)
                if row:
                    self.assertIn(row, _mod.matched_rules_in_fields(*fields))
                self.assertEqual(detect_ai_tools_in_fields(*fields), tools)

    def test_claude_code_before_a_colon_is_read_only_at_the_start_of_a_line(self):
        """ClaudeCode:<model> as the value of an Assisted-by line stays claude-trailer-01's, and
        the full-body row reads the key only where it begins the line."""
        for body, rows in (("Assisted-by: ClaudeCode:claude-opus-5", ["claude-trailer-01"]),
                           ("* ClaudeCode:claude-opus-5", ["claude-full-body-62"]),
                           ("ClaudeCode:claude-opus-5 for the docs", [])):
            with self.subTest(body=body):
                self.assertEqual(_mod.matched_rules_in_fields(*HUMAN, *HUMAN, "chore: update", body),
                                 rows)

