    def test_each_of_the_six_reads_the_new_forms_of_the_keys(self):
        """The six rows of a mistyped or spaced key keep one list of keys, so that Code,
        Implementation, the agent before the slash and the stray i are read for each tool. A model
        alone after such a key names no tool."""
        for line, row, tools, others in (
                ("Implementation assisted-by: GitHub Copilot", "copilot-full-body-40", ["Copilot"], []),
                ("Code Assisted-by: Gemini CLI", "gemini-full-body-31", ["Gemini"], []),
                ("Co-authored-by agent: OpenCode/kimi-k3", "opencode-full-body-33", ["OpenCode"], []),
                ("Code Generated-by: Claude Code", "claude-full-body-53", ["Claude"], []),
                ("Assisted-by:i OpenAI Codex", "codex-full-body-43", ["Codex"], []),
                ("Implementation assisted-by: Opus 4.8", None, [], ["tool not named"])):
            with self.subTest(line=line):
                fields = (*HUMAN, *HUMAN, "chore: update", line)
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [row] if row else [])
                self.assertEqual(_credits(line), (tools, others))

    def test_lines_beside_them_credit_nothing(self):
        """The message alone after Commit message, a key with a hyphen or a longer stray word, a
        system account or another word before the slash of Co-authored-by agent, a key of a single
        commit, a model alone that goes on into a plan, a review, feedback, a revised draft, a
        restriction or another tool, a misspelled model, a model of a tool after the colon of an
        Assisted-by line, the lines that k0sproject/rig copies from a pull request description and
        AI co-authors in a list item."""
        for body in (
                "Commit message Assisted-By: Claude Code (Opus 4.8)",
                "Test implementation assisted-by: Claude Code",
                "Code-Generated-by: Cursor",
                "Co-authored-by agent: root/GPT-5",
                "Co-authored-by agent: omp-like/gpt-5",
                "Co-authored-by agent: pip/gpt-5",
                "Assisted-by:ivan Cursor",
                "Assisted-by: WChat:Claude",
                "Generate-by: Cursours",
                "Wordsmithed-by: cursor/grok",
                "Assisted by: Opus 4.8 LLM for review of options. Fixes #834",
                "Assisted by: Opus 4.6 to plan based on ScaleODM API",
                "Assisted by: Opus 4.7 for plan",
                "Assisted by: Opus 4.6 + Codex 5.4 review",
                "Assisted by: Opus 4.6 & Codex 5.4 feedback loop",
                "Assisted by: Opus 4.8 to plan, pinpoint some changes, write some sql",
                "Assisted by: Opus 4.7 for initial draft, revised",
                "Assisted by: Opus 4.6 LLN",
                "Assisted by: Opus Fable LLM",
                "docs assisted by: Opus 4.6 LLM",
                "Assisted by: Opus4.5 and Codex GPT5.2",
                "Assisted by: omo:GLM-5.3",
                "Assisted by: Opus 4.6, Codex 5.4",
                "Assisted by: GPT-5.2, via Cursor",
                "Assisted by: Opus 4.8 LLM, with Claude Code",
                "Assisted by: ChatGPT, Claude",
                "Assisted by: Opus 4.8 LLM. Not used for the code",
                "Assisted by: Opus 4.8 LLM, tests only",
                "Assisted by: Opus 4.6 LLM. Commit message only",
                "Assisted by: google/gemini-3-pro for review",
                "Assisted by: google/gemini-2.5-pro via Cursor",
                "Generated by: Claude with sonnet",
                "Written by AI: claude-sonnet-5, claude-opus-5",
                "AI Co-author: glm-5.1 and a person",
                "- AI co-authors: Claude (Anthropic) & Codex (OpenAI)"):
            with self.subTest(body=body):
                fields = (*HUMAN, *HUMAN, "chore: update", body)
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), [])


