                ("chore: update", "AI authorship: human"),
                ("chore: update", "Contribution-attribution: OpenAI/gpt-5.6-sol"),
                ("chore: update", "<!-- contribution-attribution:v1 -->"),
                ("fix timestamp-trace option", "Assisted-by: Devin (GTP-5.6)"),
                ("chore: update", "Assisted-by: Devin: fixes the parser"),
                ("chore: update", "Assisted-by: Devin Smith"),
                ("chore: update", "Assisted-by: Devin: Claude Opus 4.7 <devin@example.com>"),
                ("Declare ruff's vendored-file excludes once in pyproject.toml (#9090)",
                 "<!--\nprovenance: claude-code session 2026-09-03, branch\n"
                 "mono-ruff-extend-exclude off dev @ 9ea04d41a\n"
                 "(rebuilt disjoint from #9089 per user request; previously stacked on\nthat branch)"),
                ("Shared:Mock: add haiku and sonnet inside model aliases", ""),
                ("Shared:AI: add claude opus inside model_name_map", ""),
                ("update .meta files with AI spell checks", ""),
                ("Shared:Components:Backdrop: refactoring with AI", ""),
