    def test_identities_beside_them_credit_nothing(self):
        """Amp as the committer of a person's commit, a person's address at ampcode.com, a longer
        local part, Amp's address of co-author lines as the author, Agent Kanban's domain without
        the subdomain of its agents, another id or no id before junie-agent, a name that contains
        junie-agent, the harness ChaosEngine at mail.grokbot.com and another local part beside
        Tali's."""
        for author, committer in (
                (("Darren Doe", "darren@example.com"), self.AMP),
                (("Ann Roe", "ann@ampcode.com"), ("Ann Roe", "ann@ampcode.com")),
                (("camp", "camp@ampcode.com"), HUMAN),
                (("Ann", "x+amp@ampcode.com"), HUMAN),
                (("Amp", "noreply@ampcode.com"), HUMAN),
                (("Bot", "bot@agent-kanban.dev"), HUMAN),
                (("junie-agent", "1247260674+junie-agent@users.noreply.github.com"), HUMAN),
                (("junie-agent", "junie-agent@users.noreply.github.com"), HUMAN),
                (("my-junie-agent", "me@example.com"), HUMAN),
                (("ChaosEngine", "chaosengine@mail.grokbot.com"),
                 ("ChaosEngine", "chaosengine@mail.grokbot.com")),
                (("X", "notalibot@mail.grokbot.com"), HUMAN)):
            with self.subTest(author=author, committer=committer):
                fields = (*author, *committer, "chore: update", "")
                self.assertEqual(_mod.matched_rules_in_fields(*fields), [])
                self.assertEqual(_mod.matched_other_rules_in_fields(*fields), [])

    def test_lines_beside_them_credit_no_amp(self):
        """A key followed by an empty line, another key or host, a thread in prose, a quoted line,
        the description alone, a negation, AMP in a later sentence or as automatic mixed
        precision, and Amp's CLI as the subject of a change."""
        for body in (
                "Amp-Thread-ID:\n\nCloses: #1118",
                "Thread-ID: https://ampcode.com/threads/T-01a1822a-68da-7125-9e7d-16e038ab0840",
                "Amp-Thread-ID: https://example.com/threads/T-01a1822a-68da-7125-9e7d-16e038ab0840",
                "See the Amp thread T-01a1822a-68da-7125-9e7d-16e038ab0840 for details.",
                "> Amp-Thread-ID: https://ampcode.com/threads/T-01a145cb-d525-72bd-8cad-4bde9fa06e44",
                "Amp-Thread-URL: https://ampcode.com/threads/T-01a145cb-d525-72bd-8cad-4bde9fa06e44",
                "Amp-Thread-ID:\n[https://example.com/threads/T-0bfe3d00-51f1-4177-ad2a-f9f5ba296b10]",
                "AI disclosure: the description was written by Amp.",
                "AI disclosure: none of this was written by Amp.",
                "AI disclosure: no code was generated by Amp.",
                "AI disclosure: I did not use Amp; the code is mine.",
                "AI disclosure: the kernel was built with AMP enabled for mixed precision.",
                "amp-cli is retained: Amp still ships and supports the CLI."):
            with self.subTest(body=body):
                self.assertEqual(_credits(body), ([], []))
        self.assertEqual(_credits("AI disclosure: written by Claude. Built with AMP."),
                         (["Claude"], []))


